window.SDT_LESSONS=window.SDT_LESSONS||{};window.SDT_LESSONS["N4L"]={"deck":"N4L","slides":[{"p":1,"title":"Lab 3 소개: 트랜스포머를 손으로 만들기","terms":["Attention","Self-Attention","Transformer","Multi-Head Attention (MHA)"],"pass1":[{"kind":"say","lines":["4주차 강의를 그대로 코드로 옮기는 실습이에요.","**트랜스포머(Transformer)** 블록을 NumPy 로, 그다음 PyTorch 로 직접 만들어요."]},{"kind":"points","head":"오늘의 여섯 부분","items":["Part 0: 환경 준비(약 2분)","Part 1: NumPy 로 **어텐션(Attention)** 세 단계, 루트 d 로 나누는 까닭","Part 2: **셀프 어텐션(Self-Attention)** 과 강의의 장벽 세 개를 숫자로","Part 3: PyTorch 로 **멀티 헤드 어텐션(Multi-Head Attention)** 모듈 만들기","Part 4: 미니 **트랜스포머(Transformer)** 블록을 학습시키고 어텐션 그림 보기","Part 5: 실제 사전 학습 모델(DistilBERT)의 진짜 헤드 들여다보기"]}],"pass2":[{"kind":"points","head":"노트북이 미리 알려 주는 것","items":["전부 Colab 무료 CPU 에서 돌아가요. GPU 가 필요 없어요.","Part 4 에서 학습하는 모델은 **파라미터(Parameter)** 약 5만 개, 학습 약 2초예요.","Part 5 에서 250MB 짜리 모델을 한 번 내려받아요.","셀을 순서대로 실행하세요. 앞서 나가면 값이 어긋나요."]},{"kind":"say","lines":["주문: 글을 토큰으로 자르고, 토큰을 벡터로 바꾸고, 벡터로 다음 토큰을 맞혀요.","오늘은 '벡터를 서로 섞는 방법' 을 **어텐션(Attention)** 으로 바꿔요."]}],"pass3":[{"kind":"prof","when":"4주차 3교시 수업","lines":["교수님: 20분밖에 안 남아서 오늘 실습은 건너뛰겠습니다.","풀 코드를 아웃풋까지 찍어서 올려놨으니 복습으로 돌려 보세요.","최대한 이 셀만 읽어도 이해할 수 있게 굉장히 친절하게 적어 놨습니다."]},{"kind":"prof","when":"4주차 3교시 수업","lines":["교수님이 말한 파트 구성이에요.","Part 1 은 2장에서 배운 **크로스 어텐션(Cross-Attention)** 개념, Part 2 는 **셀프 어텐션(Self-Attention)**,","Part 3 은 PyTorch 의 셀프 어텐션과 우리가 직접 만든 것의 차이,","Part 4 는 **트랜스포머(Transformer)** 블록, Part 5 는 층별 **헤드(Head)** 분석이에요."]}],"pass4":[{"kind":"check","q":"교수님이 Lab 3 을 수업에서 건너뛴 까닭은?","choices":["시간이 20분밖에 남지 않아서","코드에 오류가 있어서","시험 범위가 아니라서","GPU 가 없어서"],"a":0,"why":"프로젝트 안내 뒤 20분이 남아서, 출력까지 찍힌 풀 코드를 올려 두고 복습하라고 했어요."},{"kind":"check","q":"이 노트북 Part 1 이 다루는 개념은?","choices":["**크로스 어텐션(Cross-Attention)**","**층 정규화(LayerNorm)**","빔 서치","토큰화"],"a":0,"why":"교수님 말: Part 1 은 어텐션 2장에서 배운 크로스 어텐션 개념이에요."}]},{"p":2,"title":"Part 0 환경 준비: 도구 부르기와 씨앗 심기","terms":["Tensor","Parallelization","Shape"],"pass1":[{"kind":"say","lines":["쓸 도구를 불러오고, 무작위 숫자가 매번 같게 나오도록 씨앗을 심어요.","오늘은 GPU 가 필요 없어요. 모델이 작아서 CPU 가 오히려 빠를 때도 있어요."]}],"pass2":[{"kind":"pyterm","name":"import ... as ...","say":["`import numpy as np` 는 NumPy 를 np 라는 짧은 이름으로 불러와요.","`import torch.nn as nn` 은 신경망 부품 묶음이에요.","`import torch.nn.functional as F` 는 함수 모양의 부품 묶음이에요."],"example":"import numpy as np\nprint(np.array([1, 2, 3]).sum())","out":"6"},{"kind":"pyterm","name":"manual_seed 와 seed","say":["`torch.manual_seed(0)` 은 무작위 숫자의 시작점을 0 으로 고정해요.","씨앗을 같게 심으면 몇 번을 돌려도 같은 무작위 숫자가 나와요.","그래서 여러분 화면의 값과 저장된 출력이 같아요."],"example":"import torch\ntorch.manual_seed(0)\nprint(torch.randn(1).shape)","out":"torch.Size([1])"},{"kind":"pyterm","name":"set_num_threads","say":["`torch.set_num_threads(2)` 는 CPU 코어를 2개만 쓰라는 뜻이에요.","Colab 무료 등급이 코어를 2개쯤 주기 때문이에요. **병렬화(Parallelization)** 와 이어지는 설정이에요."],"example":"torch.set_num_threads(2)"}],"pass3":[{"kind":"code","head":"도구와 씨앗","file":"Lab3 노트북 셀 3","code":"import math, time\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nimport matplotlib.pyplot as plt\n\ntorch.manual_seed(0)\nnp.random.seed(0)\ntorch.set_num_threads(2)          # Colab free tier gives us ~2 cores\n\nprint(\"numpy  :\", np.__version__)\nprint(\"torch  :\", torch.__version__)\nprint(\"device : cpu (that is enough for this lab)\")","lines":[{"from":1,"to":6,"say":"수학(math), 시간(time), NumPy, PyTorch, 신경망 부품(nn), 함수 부품(F), 그림(plt)을 불러와요."},{"from":8,"to":9,"say":"PyTorch 와 NumPy 의 무작위 씨앗을 둘 다 0 으로 고정해요."},{"from":10,"to":10,"say":"CPU 코어를 2개만 쓰게 정해요. 주석처럼 Colab 무료 등급이 약 2코어를 줘요."},{"from":12,"to":14,"say":"NumPy 와 PyTorch 의 버전, 그리고 장치가 cpu 라는 것을 출력해요."}],"link":"강의 N4 p.59 Lab 3 안내"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`numpy  : 2.1.3`","`torch  : 2.11.0+cpu`","`device : cpu (that is enough for this lab)`"]}],"pass4":[{"kind":"check","q":"씨앗(manual_seed)을 고정하는 까닭은?","choices":["돌릴 때마다 같은 무작위 숫자가 나오게 하려고","속도를 올리려고","GPU 를 쓰려고","**모양(Shape)** 을 맞추려고"],"a":0,"why":"씨앗이 같으면 무작위 **텐서(Tensor)** 도 같아서, 저장된 출력과 내 화면이 같아져요."},{"kind":"warn","head":"헷갈리는 점","items":["버전 숫자(numpy 2.1.3, torch 2.11.0)는 여러분 환경에 따라 달라요.","셀을 순서대로 돌리지 않으면 씨앗이 어긋나서 뒤 숫자가 달라져요."]}]},{"p":3,"title":"1.1 어텐션의 전부는 세 줄","terms":["Attention","Query","Key","Value","Softmax","Weighted Sum","Attention Score","Cross-Attention"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)** 은 딱 세 단계예요.","점수 매기기 → **소프트맥스(Softmax)** → **가중합(Weighted Sum)**.","강의 N4 p.21-23 의 세 단계 그대로예요."]},{"kind":"analogy","head":"어텐션은 부드러운 사전 찾기","scene":"파이썬 사전은 키 하나가 딱 맞아야 값을 줘요. 어텐션은 모든 키와 조금씩 맞고, 값들을 섞어서 줘요.","map":[["사전의 찾는 말","**쿼리(Query)**"],["사전의 표제어","**키(Key)**"],["표제어의 뜻풀이","**밸류(Value)**"],["섞어서 내놓기","**가중합(Weighted Sum)**"]]}],"pass2":[{"kind":"points","head":"영어 제목과 문장의 뜻","items":["**The whole idea in three lines** = 핵심 생각은 세 줄이면 끝이에요.","**score → softmax → weighted sum** = 점수 → 소프트맥스 → 가중합.","**A query asks a question** = **쿼리(Query)** 가 질문을 던져요.","**Every key advertises what it has** = 각 **키(Key)** 가 자기를 광고해요.","**nothing is hidden** = 숨겨진 장치는 하나도 없어요."]},{"kind":"compare","head":"세 벡터의 역할","cols":["이름","하는 일"],"rows":[["**쿼리(Query)**","지금 내가 무엇을 찾는지"],["**키(Key)**","나는 이런 걸 갖고 있다는 이름표"],["**밸류(Value)**","뽑히면 실제로 건네줄 내용"]]},{"kind":"points","head":"이 셀이 노리는 것","items":["**쿼리(Query)** 를 2번 **키(Key)** 와 거의 같게 만들어 둬요.","그러면 출력이 2번 **밸류(Value)** 와 거의 같게 나와야 해요.","여기서는 키와 밸류를 우리가 그냥 줬어요. 그래서 **크로스 어텐션(Cross-Attention)** 쪽 그림이에요."]}],"pass3":[{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 스코어를 계산하고, 노멀라이즈 해서 웨이트를 만들고,","웨이티드 썸으로 컨텍스트 벡터를 만들고, 그걸로 예측을 합니다.","이 네 단계가 **어텐션(Attention)** 에 가장 중요한 겁니다."]},{"kind":"points","head":"강의와 짝","items":["N4 p.20 Soft Dictionary Lookup 이 이 쪽의 비유예요.","N4 p.21 Step 1 이 **어텐션 점수(Attention Score)** 구하기,","N4 p.22 Step 2 가 **소프트맥스(Softmax)**, N4 p.23 Step 3 이 **가중합(Weighted Sum)** 이에요."]}],"pass4":[{"kind":"check","q":"어텐션의 출력은 무엇들의 가중 평균인가요?","choices":["**밸류(Value)** 들","**키(Key)** 들","**쿼리(Query)** 들","**어텐션 점수(Attention Score)** 들"],"a":0,"why":"점수는 **키(Key)** 로 매기지만, 실제로 섞어서 내놓는 것은 **밸류(Value)** 예요."}]},{"p":4,"title":"어텐션 세 줄을 NumPy 로 직접","terms":["Softmax","Attention Score","Attention Weight","Weighted Sum","Dot Product","Query","Key","Value","Attention"],"pass1":[{"kind":"say","lines":["**어텐션(Attention)** 을 파이썬 세 줄로 씁니다.","점수 → **소프트맥스(Softmax)** → **가중합(Weighted Sum)**, 정말 이게 전부예요."]}],"pass2":[{"kind":"pyterm","name":"def 로 함수 만들기","say":["`def softmax(x, axis=-1):` 는 softmax 라는 함수를 정의해요.","`axis=-1` 은 기본값이에요. 안 적으면 마지막 축을 뜻해요.","`return` 이 결과를 돌려줘요."],"example":"def twice(x):\n    return x * 2\nprint(twice(5))","out":"10"},{"kind":"pyterm","name":"np.array","say":["`np.array([[1., 0.], [0., 1.]])` 는 2행 2열 숫자 표를 만들어요.","숫자 뒤의 점(1.)은 정수가 아니라 소수라는 표시예요."],"example":"import numpy as np\nprint(np.array([[1., 0.], [0., 1.]]).shape)","out":"(2, 2)"},{"kind":"pyterm","name":"행렬 곱 기호 @","say":["`keys @ query` 는 행렬 곱이에요. 각 행과 **쿼리(Query)** 의 **내적(Dot Product)** 을 한 번에 구해요.","(4, 3) @ (3,) 은 (4,) 가 돼요. 키가 4개니까 점수도 4개예요."],"example":"print(np.array([[1., 0.], [0., 1.]]) @ np.array([3., 5.]))","out":"[3. 5.]"},{"kind":"pyterm","name":"axis 와 keepdims","say":["`x.max(axis=-1, keepdims=True)` 는 마지막 축에서 최댓값을 찾고 칸 모양을 유지해요.","가장 큰 값을 먼저 빼 주면 exp 가 너무 커져서 넘치는 일을 막아요. 결과는 똑같아요."],"example":"import numpy as np\nx = np.array([1., 2., 3.])\nprint(np.exp(x - x.max()).round(3))","out":"[0.135 0.368 1.   ]"}],"pass3":[{"kind":"formula","head":"어텐션 세 단계","tex":"s = K q,\\qquad \\alpha = \\mathrm{softmax}(s),\\qquad o = \\alpha^\\top V","parts":[{"sym":"K q","say":"각 키와 쿼리의 내적, 곧 어텐션 점수 s"},{"sym":"\\mathrm{softmax}(s)","say":"합이 1 인 어텐션 가중치 알파"},{"sym":"\\alpha^\\top V","say":"밸류들의 가중합, 곧 출력 o"}],"whole":"강의 N4 p.24 의 네 식 중 앞 세 줄이 이 코드의 18, 19, 20번 줄이에요."},{"kind":"code","head":"네 칸짜리 기억 장치에서 하나 꺼내 오기","file":"Lab3 노트북 셀 5","code":"def softmax(x, axis=-1):\n    x = x - x.max(axis=axis, keepdims=True)      # numerically safe\n    e = np.exp(x)\n    return e / e.sum(axis=axis, keepdims=True)\n\n# four memory slots: each has a key (what it advertises) and a value (what it hands over)\nkeys   = np.array([[ 1., 0., 0.],      # key 0\n                   [ 0., 1., 0.],      # key 1\n                   [ 0., 0., 1.],      # key 2\n                   [-1., 0., 0.]])     # key 3\nvalues = np.array([[10., 0.],\n                   [ 0., 10.],\n                   [ 5.,  5.],\n                   [-9., -9.]])\n\nquery = np.array([0.5, 0.0, 3.0])      # points mostly along key 2\n\nscores  = keys @ query                 # (1) score: how well does each key match?\nweights = softmax(scores)              # (2) softmax: turn scores into a distribution\noutput  = weights @ values             # (3) mix: weighted average of the values\n\nprint(\"scores  :\", np.round(scores, 3))\nprint(\"weights :\", np.round(weights, 3), \" (sum =\", round(weights.sum(), 6), \")\")\nprint(\"output  :\", np.round(output, 2))\nprint(\"value 2 :\", values[2], \"  <- almost exactly what we got back\")","lines":[{"from":1,"to":4,"say":"안전한 **소프트맥스(Softmax)** 함수예요. 최댓값을 빼고 exp 를 씌운 뒤 전체 합으로 나눠요."},{"from":6,"to":10,"say":"**키(Key)** 4개예요. 주석처럼 각 칸이 '나는 이런 걸 갖고 있다' 고 광고해요."},{"from":11,"to":14,"say":"**밸류(Value)** 4개예요. 뽑히면 실제로 건네줄 내용이고 2칸짜리예요."},{"from":16,"to":16,"say":"**쿼리(Query)** 예요. 주석처럼 대부분 2번 키 쪽을 향해요."},{"from":18,"to":18,"say":"(1) 점수: 각 키와 쿼리의 **내적(Dot Product)** 을 구해요. 4개 숫자가 나와요."},{"from":19,"to":19,"say":"(2) **소프트맥스(Softmax)**: 점수를 합이 1 인 **어텐션 가중치(Attention Weight)** 로 바꿔요."},{"from":20,"to":20,"say":"(3) 섞기: 가중치로 **밸류(Value)** 들의 **가중합(Weighted Sum)** 을 내요."},{"from":22,"to":25,"say":"점수, 가중치와 그 합, 출력, 그리고 2번 밸류를 나란히 출력해요."}],"link":"강의 N4 p.21-24 어텐션 세 단계와 네 식"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`scores  : [ 0.5  0.   3.  -0.5]`","`weights : [0.071 0.043 0.861 0.026]  (sum = 1.0 )`","`output  : [4.78 4.5 ]`","`value 2 : [5. 5.]   <- almost exactly what we got back`"]},{"kind":"steps","head":"점수와 가중치를 손으로","steps":["키 0 은 [1, 0, 0] 이라 쿼리 [0.5, 0, 3] 과의 내적은 0.5 예요.","키 1 은 [0, 1, 0] 이라 0, 키 2 는 [0, 0, 1] 이라 3, 키 3 은 [-1, 0, 0] 이라 -0.5 예요.","exp 를 씌우면 2번 칸만 크게 남아요. 나눠 주면 0.861 이 2번 칸에 몰려요.","출력 = 0.071x10 + 0.043x0 + 0.861x5 + 0.026x(-9) = 4.78 (첫 칸)"],"answer":"출력 [4.78, 4.50] 은 2번 **밸류(Value)** [5, 5] 와 거의 같아요. 예상대로예요."},{"kind":"points","head":"읽는 요령","items":["`sum = 1.0` 은 **소프트맥스(Softmax)** 가 제대로 확률을 만들었다는 확인이에요.","쿼리가 키 2 를 가장 닮았으니 밸류 2 가 거의 그대로 나온 거예요."]}],"pass4":[{"kind":"check","q":"**어텐션 가중치(Attention Weight)** 가 [0.071, 0.043, 0.861, 0.026] 일 때, 출력에 가장 크게 기여하는 것은?","choices":["2번 **밸류(Value)**","0번 **밸류(Value)**","2번 **키(Key)**","**쿼리(Query)**"],"a":0,"why":"가중치 0.861 이 2번 자리에 몰려 있고, 곱해지는 것은 키가 아니라 밸류예요."},{"kind":"warn","head":"흔한 실수","items":["점수 계산에는 **키(Key)** 를 쓰고, 가중합에는 **밸류(Value)** 를 써요. 둘을 바꾸면 안 돼요.","**소프트맥스(Softmax)** 에서 최댓값을 빼는 것은 값을 바꾸는 게 아니라 넘침을 막는 요령이에요."]}]},{"p":5,"title":"1.2 날카로운 가중치와 평평한 가중치","terms":["Softmax","Attention Weight","Attention Distribution","Attention Score"],"pass1":[{"kind":"say","lines":["같은 세 줄인데, 점수의 크기에 따라 결과가 크게 달라져요.","점수가 크면 거의 한 곳만 보고, 작으면 골고루 봐요."]},{"kind":"analogy","head":"가중치의 모양","scene":"손전등 같아요. 좁게 비추면 한 곳만 환하고, 넓게 비추면 온 방이 어스름해요.","map":[["좁은 손전등","날카로운 **어텐션 분포(Attention Distribution)**"],["넓은 손전등","평평한 **어텐션 분포(Attention Distribution)**"],["빛의 세기 조절","**어텐션 점수(Attention Score)** 의 크기"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Sharp weights vs flat weights** = 날카로운 가중치 대 평평한 가중치.","**Large scores → an almost one-hot distribution** = 점수가 크면 한 칸만 1 에 가까워요.","**Small scores → an almost uniform distribution** = 점수가 작으면 거의 고르게 나뉘어요.","**it is exactly why the Transformer divides by root d** = 루트 d 로 나누는 이유가 바로 이것이에요."]},{"kind":"pyterm","name":"for ... in (a, b, c)","say":["괄호로 묶은 값들을 하나씩 꺼내 같은 일을 되풀이해요.","`for scale in (0.2, 1.0, 6.0):` 은 0.2, 1.0, 6.0 에 대해 차례로 돌아요."],"example":"for s in (1, 2, 3):\n    print(s * 10)","out":"10\n20\n30"},{"kind":"pyterm","name":"f-string 의 칸 맞추기","say":["`f\"{scale:>4}\"` 는 오른쪽 정렬로 4칸을 써요.","`f\"{w.max():.3f}\"` 는 소수 셋째 자리까지만 보여 줘요.","표처럼 줄을 맞추려고 쓰는 문법이에요."],"example":"x = 0.38123\nprint(f\"{x:.3f}\")","out":"0.381"}],"pass3":[{"kind":"code","head":"같은 점수에 배율만 바꿔 보기","file":"Lab3 노트북 셀 7","code":"base = np.array([2.0, 1.4, 1.0, 0.8, 0.5, 0.3])\n\nfor scale in (0.2, 1.0, 6.0):\n    w = softmax(base * scale)\n    print(f\"scale={scale:>4}  max weight={w.max():.3f}   weights={np.round(w, 3)}\")","lines":[{"from":1,"to":1,"say":"여섯 칸짜리 기본 점수를 만들어요. 가장 큰 값이 2.0 이에요."},{"from":3,"to":3,"say":"배율 0.2, 1.0, 6.0 을 차례로 넣어 봐요."},{"from":4,"to":4,"say":"점수 전체에 배율을 곱한 뒤 **소프트맥스(Softmax)** 를 걸어요."},{"from":5,"to":5,"say":"배율, 가장 큰 **어텐션 가중치(Attention Weight)**, 여섯 칸 전부를 한 줄로 출력해요."}],"link":"강의 N4 p.19 Sharp weights = look here, Flat weights = everything matters"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`scale= 0.2  max weight=0.202   weights=[0.202 0.179 0.166 0.159 0.15  0.144]`","`scale= 1.0  max weight=0.381   weights=[0.381 0.209 0.14  0.115 0.085 0.07 ]`","`scale= 6.0  max weight=0.970   weights=[0.97  0.027 0.002 0.001 0.    0.   ]`"]},{"kind":"steps","head":"숫자로 확인","steps":["배율 0.2 면 점수가 [0.4, 0.28, ...] 로 작아요. 가장 큰 칸도 0.202 뿐이에요.","배율 1.0 이면 가장 큰 칸이 0.381 이에요. 적당히 한 곳을 가리켜요.","배율 6.0 이면 점수가 [12, 8.4, ...] 로 커요. 가장 큰 칸이 0.970 이에요.","여섯 칸이 모두 같다면 1/6 = 0.167 이었을 거예요."],"answer":"점수의 크기만 바꿨는데 **어텐션 분포(Attention Distribution)** 가 평평 → 날카로움으로 변해요."}],"pass4":[{"kind":"check","q":"배율 6.0 에서 가장 큰 **어텐션 가중치(Attention Weight)** 가 0.970 이라는 뜻은?","choices":["나머지 다섯 칸을 사실상 안 본다는 뜻","점수가 확률이라는 뜻","**소프트맥스(Softmax)** 가 틀렸다는 뜻","가중치 합이 6 이라는 뜻"],"a":0,"why":"한 칸에 97% 가 몰리면 다른 칸의 **밸류(Value)** 는 거의 반영되지 않아요."},{"kind":"warn","head":"헷갈리는 점","items":["점수의 순서는 세 경우 모두 같아요. 달라진 것은 크기뿐이에요.","날카로운 게 늘 좋은 것도, 평평한 게 늘 나쁜 것도 아니에요. 모델이 골라 배워요."]}]},{"p":6,"title":"1.3 왜 루트 d 로 나누나: 직접 재 보기","terms":["Dot Product","Scaled Dot-Product Attention","Attention Score","Softmax"],"pass1":[{"kind":"say","lines":["강의는 **내적(Dot Product)** 의 분산이 d_k 라고 했어요.","그러면 표준편차는 루트 d_k 만큼 커져요. 믿지 말고 재 봐요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Why divide by root d ?** = 왜 루트 d 로 나누나요?","**Var(q dot k) = d_k** = 내적의 흩어진 정도가 차원 수만큼 커져요.","**the scores are routinely plus or minus 20** = d_k 가 512 면 점수가 보통 20 안팎까지 커져요.","**Let us measure it instead of trusting the formula** = 식을 믿지 말고 직접 재 봅시다."]},{"kind":"pyterm","name":"np.random.default_rng","say":["`rng = np.random.default_rng(0)` 은 씨앗 0 짜리 난수 생성기를 만들어요.","`rng.normal(size=(20000, d))` 은 평균 0, 표준편차 1 인 숫자를 그 **모양(Shape)** 대로 뽑아요."],"example":"import numpy as np\nrng = np.random.default_rng(0)\nprint(rng.normal(size=(2, 3)).shape)","out":"(2, 3)"},{"kind":"pyterm","name":"(q * k).sum(axis=1) 과 .std()","say":["`q * k` 는 같은 자리끼리 곱해요. 거기에 `.sum(axis=1)` 로 한 줄씩 더하면 **내적(Dot Product)** 이에요.","`.std()` 는 표준편차, 곧 숫자들이 평균에서 얼마나 흩어졌는지예요."],"example":"import numpy as np\nq = np.array([[1., 2.]])\nk = np.array([[3., 4.]])\nprint((q * k).sum(axis=1))","out":"[11.]"}],"pass3":[{"kind":"formula","head":"내적의 흩어짐","tex":"\\mathrm{Var}(q\\cdot k)=d_k \\;\\Rightarrow\\; \\mathrm{sd}(q\\cdot k)=\\sqrt{d_k}","parts":[{"sym":"q\\cdot k","say":"두 벡터의 내적, 곧 어텐션 점수"},{"sym":"d_k","say":"키 벡터의 칸 수(차원)"},{"sym":"\\sqrt{d_k}","say":"점수의 표준편차. 차원이 커지면 점수도 커져요"}],"whole":"그래서 점수를 루트 d_k 로 나누면 흩어짐이 다시 1 로 돌아와요. 이것이 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)** 이에요."},{"kind":"code","head":"차원을 키우며 점수의 표준편차 재기","file":"Lab3 노트북 셀 9","code":"rng = np.random.default_rng(0)\n\nprint(\" d_k    measured sd of q,k    sqrt(d_k)\")\nfor d in (8, 64, 512):\n    q = rng.normal(size=(20000, d))\n    k = rng.normal(size=(20000, d))\n    s = (q * k).sum(axis=1)\n    print(f\"{d:>4}    {s.std():>16.2f}    {math.sqrt(d):>9.2f}\")","lines":[{"from":1,"to":1,"say":"씨앗 0 짜리 난수 생성기를 만들어요."},{"from":3,"to":3,"say":"표의 머리글을 출력해요. d_k, 잰 표준편차, 루트 d_k 세 칸이에요."},{"from":4,"to":4,"say":"차원 8, 64, 512 를 차례로 시험해요."},{"from":5,"to":6,"say":"각 차원마다 **쿼리(Query)** 20000개, **키(Key)** 20000개를 무작위로 뽑아요."},{"from":7,"to":7,"say":"같은 자리끼리 곱해 더해서 20000개의 **내적(Dot Product)** 을 구해요."},{"from":8,"to":8,"say":"잰 표준편차와 루트 d_k 를 나란히 출력해요."}],"link":"강의 N4 p.38 Why the Scaled Dot Product"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`d_k    measured sd of q,k    sqrt(d_k)`","`8                2.86         2.83`","`64                8.02         8.00`","`512               22.57        22.63`"]},{"kind":"steps","head":"표가 말해 주는 것","steps":["d_k = 8 일 때 잰 값 2.86, 루트 8 = 2.83","d_k = 64 일 때 잰 값 8.02, 루트 64 = 8.00","d_k = 512 일 때 잰 값 22.57, 루트 512 = 22.63","세 줄 모두 두 숫자가 거의 같아요."],"answer":"강의의 식이 맞았어요. 차원이 512 면 **어텐션 점수(Attention Score)** 가 보통 20 을 넘나들어요."}],"pass4":[{"kind":"check","q":"d_k = 512 에서 점수의 표준편차가 약 22.6 이면 무슨 일이 생기나요?","choices":["**소프트맥스(Softmax)** 가 거의 한 칸만 보게 포화돼요","점수가 0 이 돼요","**키(Key)** 가 사라져요","계산이 느려져요"],"a":0,"why":"앞 쪽에서 본 배율 6.0 과 같은 상황이에요. 그래서 루트 d_k 로 나눠 줘요."},{"kind":"warn","head":"헷갈리는 점","items":["나누는 값은 루트 d_k 이지 d_k 가 아니에요. 분산이 d_k 라서 표준편차는 루트 d_k 예요.","잰 값과 루트 값이 소수점 둘째 자리에서 조금 다른 것은 무작위 표본이라 그래요."]}]},{"p":7,"title":"포화된 소프트맥스는 기울기를 잃어요","terms":["Softmax","Gradient","Vanishing Gradient","Scaled Dot-Product Attention","Attention Weight"],"pass1":[{"kind":"say","lines":["점수가 너무 크면 **소프트맥스(Softmax)** 가 포화돼요.","포화되면 **기울기(Gradient)** 가 거의 사라져서, 그 층은 배우지 못해요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**its gradient almost disappears** = 기울기가 거의 사라져요.","**A layer that cannot pass a gradient cannot learn** = 기울기를 못 흘리는 층은 학습이 안 돼요.","**the saturated softmax passes ~8x less gradient** = 포화된 소프트맥스는 기울기를 약 8분의 1 만 흘려요.","3주차 RNN 의 **기울기 소실(Vanishing Gradient)** 과 원인은 다르지만 증상은 같아요."]},{"kind":"pyterm","name":"requires_grad_() 와 backward()","say":["`z.requires_grad_(True)` 는 '이 값에 대한 **기울기(Gradient)** 를 기록해 줘' 라는 표시예요.","결과에 `.backward()` 를 부르면 거꾸로 따라가며 계산하고 `z.grad` 에 기울기를 넣어요.","3주차 실습에서 배운 자동 미분이에요."],"example":"import torch\nz = torch.tensor([2.0], requires_grad=True)\n(z * z).sum().backward()\nprint(z.grad)","out":"tensor([4.])"},{"kind":"pyterm","name":".softmax(-1) 과 .item()","say":["`z.softmax(-1)` 은 마지막 축에 **소프트맥스(Softmax)** 를 걸어요.","`.item()` 은 숫자 하나짜리 **텐서(Tensor)** 에서 파이썬 숫자를 꺼내요.","`.abs().max()` 는 절댓값 중 가장 큰 것이에요."],"example":"import torch\nprint(torch.tensor([-3.0]).abs().max().item())","out":"3.0"}],"pass3":[{"kind":"code","head":"배율 1 과 배율 6 의 기울기 비교","file":"Lab3 노트북 셀 11","code":"for scale in (1.0, 6.0):\n    z = torch.tensor([2.0, 1.4, 1.0, 0.8, 0.5, 0.3]) * scale\n    z.requires_grad_(True)\n    p = z.softmax(-1)\n    p.max().backward()                      # how much does the top weight move?\n    print(f\"scale={scale:>4}   max weight={p.max().item():.4f}   \"\n          f\"largest |gradient|={z.grad.abs().max().item():.3e}\")\n\nprint(\"\\n-> the saturated softmax passes ~8x less gradient. Dividing by sqrt(d_k)\")\nprint(\"   keeps the scores in the range where softmax still has a slope.\")","lines":[{"from":1,"to":2,"say":"배율 1.0 과 6.0 을 차례로 넣고, 앞에서 쓴 여섯 칸 점수에 배율을 곱해요."},{"from":3,"to":3,"say":"이 **텐서(Tensor)** 의 **기울기(Gradient)** 를 기록하라고 표시해요."},{"from":4,"to":4,"say":"**소프트맥스(Softmax)** 를 걸어 **어텐션 가중치(Attention Weight)** 를 만들어요."},{"from":5,"to":5,"say":"가장 큰 가중치 하나에 대해 거꾸로 미분해요. 주석처럼 '그 칸이 얼마나 움직일 수 있나' 를 재요."},{"from":6,"to":7,"say":"배율, 가장 큰 가중치, 기울기 절댓값의 최댓값을 한 줄로 출력해요."},{"from":9,"to":10,"say":"포화된 소프트맥스는 기울기를 약 8분의 1 만 흘린다고, 루트 d_k 가 그래서 필요하다고 알려 줘요."}],"link":"강의 N4 p.38 a saturated softmax has almost no gradient"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`scale= 1.0   max weight=0.3811   largest |gradient|=2.359e-01`","`scale= 6.0   max weight=0.9702   largest |gradient|=2.891e-02`","`-> the saturated softmax passes ~8x less gradient. Dividing by sqrt(d_k)`","`keeps the scores in the range where softmax still has a slope.`"]},{"kind":"steps","head":"두 숫자를 나눠 보기","steps":["배율 1.0: 가장 큰 가중치 0.3811, 기울기 0.2359","배율 6.0: 가장 큰 가중치 0.9702, 기울기 0.02891","0.2359 나누기 0.02891 은 약 8.2 예요."],"answer":"포화되면 기울기가 약 8분의 1 로 줄어요. 3주차의 **기울기 소실(Vanishing Gradient)** 과 같은 증상이에요."},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 소프트맥스 안에 들어가는 닷 프로덕트 값이 너무 커지면","큰 값에 너무 몰리게 돼서 굉장히 뾰족한 분포가 만들어집니다.","그래서 루트 d_k 로 스케일링 해 준다고 보면 됩니다."]}],"pass4":[{"kind":"check","q":"**스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)** 에서 루트 d_k 로 나누지 않으면?","choices":["**소프트맥스(Softmax)** 가 포화돼 **기울기(Gradient)** 가 거의 안 흘러요","점수가 음수가 돼요","**밸류(Value)** 가 사라져요","메모리를 더 써요"],"a":0,"why":"포화 → 기울기 약 8분의 1 → 학습이 안 돼요. 시험에 나오기 좋은 한 줄이에요."},{"kind":"warn","head":"헷갈리는 점","items":["루트 d_k 는 장식이 아니라 학습을 살리는 장치예요.","0.02891 은 0.2359 보다 한 자리 작아요. e 뒤 숫자(e-01, e-02)를 꼭 보세요."]}]},{"p":8,"title":"Part 2 셀프 어텐션: 한 문장에서 Q, K, V 를 만들기","terms":["Self-Attention","Query","Key","Value","Attention Weight","Scaled Dot-Product Attention","Parallelization","Shape","Cross-Attention"],"pass1":[{"kind":"say","lines":["Part 1 에서는 **키(Key)** 와 **밸류(Value)** 를 우리가 그냥 줬어요.","**셀프 어텐션(Self-Attention)** 에서는 토큰 스스로 세 가지를 만들어요."]},{"kind":"analogy","head":"한 사람이 세 역할","scene":"회의에서 한 사람이 질문도 하고, 명찰도 달고, 자료도 건네요. 역할만 셋이지 사람은 하나예요.","map":[["질문","**쿼리(Query)**"],["명찰","**키(Key)**"],["건네는 자료","**밸류(Value)**"],["같은 사람","같은 토큰 벡터 x"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Q, K, V from one sequence** = 세 가지가 모두 같은 문장에서 나와요.","**every token produces its own query, key and value** = 토큰마다 자기 쿼리, 키, 밸류를 내놔요.","**through three learned linear maps** = 학습되는 행렬 세 개를 곱해서 만들어요."]},{"kind":"compare","head":"둘의 차이","cols":["이름","쿼리는 어디서","키와 밸류는 어디서"],"rows":[["**크로스 어텐션(Cross-Attention)**","디코더 쪽","인코더 쪽(다른 시퀀스)"],["**셀프 어텐션(Self-Attention)**","같은 시퀀스","같은 시퀀스"]]},{"kind":"pyterm","name":"함수의 기본값과 None","say":["`def self_attention(X, Wq, Wk, Wv, mask=None):` 에서 mask 는 안 주면 None 이에요.","`if mask is not None:` 은 '마스크를 줬을 때만' 이라는 뜻이에요."],"example":"def f(a, b=None):\n    return a if b is None else a + b\nprint(f(1), f(1, 2))","out":"1 3"},{"kind":"pyterm","name":".T 와 np.where","say":["`K.T` 는 행과 열을 뒤집은 전치예요. (5, 16) 이 (16, 5) 가 돼요.","`np.where(mask, a, b)` 는 mask 가 참인 자리는 a, 거짓인 자리는 b 를 골라요."],"example":"import numpy as np\nprint(np.array([[1., 2.]]).T.shape)","out":"(2, 1)"},{"kind":"pyterm","name":"여러 값 한 번에 대입","say":["`Q, K, V = X @ Wq, X @ Wk, X @ Wv` 는 세 계산을 한 줄에 써요.","`return A @ V, A` 처럼 두 값을 함께 돌려줄 수도 있어요."],"example":"a, b = 1 + 1, 2 * 3\nprint(a, b)","out":"2 6"}],"pass3":[{"kind":"formula","head":"셀프 어텐션의 식","tex":"\\mathrm{Attention}(Q,K,V)=\\mathrm{softmax}\\!\\left(\\frac{QK^\\top}{\\sqrt{d_k}}\\right)V","parts":[{"sym":"Q","say":"쿼리를 모두 쌓은 행렬. 행 하나가 토큰 하나의 질문"},{"sym":"K^\\top","say":"키 행렬을 눕힌 것. 모든 쿼리와 모든 키를 한 번에 비교해요"},{"sym":"\\sqrt{d_k}","say":"점수가 커지는 것을 되돌리는 나눗셈"},{"sym":"V","say":"뽑힌 만큼 건네줄 밸류 행렬"}],"whole":"강의 N4 p.36-37 의 식 그대로예요. 반복문이 없어서 **병렬화(Parallelization)** 가 잘 돼요."},{"kind":"code","head":"다섯 토큰짜리 문장으로 셀프 어텐션","file":"Lab3 노트북 셀 13","code":"n, d = 5, 16                    # 5 tokens, 16 dimensions\nX = rng.normal(size=(n, d))     # our \"sentence\": 5 token vectors\n\nWq = rng.normal(size=(d, d)) * 0.3\nWk = rng.normal(size=(d, d)) * 0.3\nWv = rng.normal(size=(d, d)) * 0.3\n\ndef self_attention(X, Wq, Wk, Wv, mask=None):\n    Q, K, V = X @ Wq, X @ Wk, X @ Wv          # three projections of the SAME X\n    scores = Q @ K.T / math.sqrt(Q.shape[-1])  # (n, n) -- every token vs every token\n    if mask is not None:\n        scores = np.where(mask, scores, -np.inf)\n    A = softmax(scores)                        # attention weights, rows sum to 1\n    return A @ V, A\n\nout, A = self_attention(X, Wq, Wk, Wv)\n\nprint(\"X     :\", X.shape, \" (n tokens, d dims)\")\nprint(\"A     :\", A.shape, \" (n x n: row i = where token i looks)\")\nprint(\"out   :\", out.shape)\nprint(\"\\nattention matrix (rows sum to 1):\")\nprint(np.round(A, 2))\nprint(\"row sums:\", np.round(A.sum(axis=1), 6))","lines":[{"from":1,"to":2,"say":"토큰 5개, 차원 16 으로 정하고, 무작위 숫자로 '문장' X 를 만들어요."},{"from":4,"to":6,"say":"학습될 행렬 세 개 Wq, Wk, Wv 를 만들어요. 0.3 을 곱해 값을 작게 해 둬요."},{"from":8,"to":8,"say":"**셀프 어텐션(Self-Attention)** 함수를 정의해요. mask 는 안 주면 없는 것으로 쳐요."},{"from":9,"to":9,"say":"같은 X 에 세 행렬을 곱해 **쿼리(Query)**, **키(Key)**, **밸류(Value)** 를 만들어요."},{"from":10,"to":10,"say":"모든 쿼리와 모든 키를 비교하고 루트 d_k 로 나눠요. 주석처럼 (n, n) 크기예요."},{"from":11,"to":12,"say":"마스크를 줬으면 볼 수 없는 자리의 점수를 음의 무한대로 바꿔요."},{"from":13,"to":13,"say":"**소프트맥스(Softmax)** 로 행마다 합이 1 인 **어텐션 가중치(Attention Weight)** 를 만들어요."},{"from":14,"to":14,"say":"가중치로 밸류를 섞은 출력과 가중치 행렬 둘 다 돌려줘요."},{"from":16,"to":16,"say":"함수를 불러 out 과 A 를 받아요."},{"from":18,"to":20,"say":"X, A, out 의 **모양(Shape)** 을 출력해요. 주석에 뜻이 적혀 있어요."},{"from":21,"to":23,"say":"어텐션 행렬을 소수 둘째 자리로 찍고, 행 합이 정말 1 인지 확인해요."}],"link":"강의 N4 p.34-37 Queries, Keys and Values, 그리고 행렬 형태"},{"kind":"points","head":"저장된 출력 1: 모양","items":["`X     : (5, 16)  (n tokens, d dims)`","`A     : (5, 5)  (n x n: row i = where token i looks)`","`out   : (5, 16)`","`attention matrix (rows sum to 1):`"]},{"kind":"points","head":"저장된 출력 2: 어텐션 행렬과 행 합","items":["`[[0.05 0.18 0.62 0.1  0.05]`","`[0.01 0.75 0.06 0.01 0.16]`","`[0.06 0.09 0.38 0.36 0.11]`","`[0.05 0.85 0.01 0.06 0.03]`","`[0.15 0.25 0.09 0.31 0.2 ]]`","`row sums: [1. 1. 1. 1. 1.]`"]},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 쿼리, 키, 밸류 이 3개의 컨셉을 이해해야","뒤에 트랜스포머를 이해할 수 있고 자연어 처리를 이해할 수 있습니다.","그리고 셀프 어텐션의 가장 큰 장점은 **병렬화(Parallelization)**, 패러럴이 핵심이에요."]}],"pass4":[{"kind":"check","q":"A 의 **모양(Shape)** 이 (5, 5) 인 까닭은?","choices":["토큰 5개가 서로 서로를 다 보기 때문","차원이 5 라서","**밸류(Value)** 가 5칸이라서","무작위라서"],"a":0,"why":"행 i 는 '토큰 i 가 어디를 보는지' 예요. 토큰이 n 개면 어텐션 행렬은 n x n 이에요."},{"kind":"warn","head":"헷갈리는 점","items":["Wq, Wk, Wv 는 자리마다 다른 게 아니라 모든 자리가 같은 행렬을 나눠 써요.","출력 out 의 모양은 입력 X 와 같은 (5, 16) 이에요. 모양이 유지돼야 블록을 쌓을 수 있어요."]}]},{"p":9,"title":"2.1 장벽 1: 셀프 어텐션은 순서를 몰라요","terms":["Permutation Equivariance","Self-Attention","Positional Encoding","Attention"],"pass1":[{"kind":"say","lines":["강의는 **셀프 어텐션(Self-Attention)** 이 **순열 등변성(Permutation Equivariance)** 을 갖는다고 했어요.","입력을 섞으면 출력도 똑같이 섞일 뿐이에요. 정말 그런지 숫자로 확인해요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**self-attention does not know about order** = 셀프 어텐션은 순서를 몰라요.","**shuffle the input and the output just shuffles the same way** = 입력을 섞으면 출력도 같은 식으로 섞여요.","**dog bites man and man bites dog** = 개가 사람을 문다와 사람이 개를 문다.","**Order is simply not in the mechanism** = 순서는 계산 장치 안에 아예 없어요."]},{"kind":"pyterm","name":"배열로 골라 뽑기","say":["`perm = np.array([2, 0, 4, 1, 3])` 처럼 번호 배열을 만들고 `X[perm]` 으로 행 순서를 바꿔요.","2번 행이 맨 앞, 0번 행이 그다음, 이런 식이에요."],"example":"import numpy as np\nX = np.array([10., 20., 30.])\nprint(X[np.array([2, 0, 1])])","out":"[30. 10. 20.]"},{"kind":"pyterm","name":"받지 않을 값은 밑줄","say":["`out_shuffled_input, _ = self_attention(...)` 의 밑줄은 '이 값은 안 쓸게요' 라는 뜻이에요.","함수가 두 값을 돌려주는데 하나만 필요할 때 써요."],"example":"a, _ = (1, 2)\nprint(a)","out":"1"}],"pass3":[{"kind":"formula","head":"순열 등변성","tex":"\\mathrm{SA}(PX)=P\\,\\mathrm{SA}(X)","parts":[{"sym":"P","say":"순서를 섞는 조작(퍼뮤테이션)"},{"sym":"\\mathrm{SA}(PX)","say":"섞고 나서 셀프 어텐션 하기"},{"sym":"P\\,\\mathrm{SA}(X)","say":"셀프 어텐션 하고 나서 섞기"}],"whole":"두 결과가 같다는 것이 **순열 등변성(Permutation Equivariance)** 이에요. 강의 N4 p.40 의 그 식이에요."},{"kind":"code","head":"섞고 나서와 섞기 전, 두 결과 비교","file":"Lab3 노트북 셀 15","code":"perm = np.array([2, 0, 4, 1, 3])                  # some shuffle\n\nout_shuffled_input, _ = self_attention(X[perm], Wq, Wk, Wv)   # SA(PX)\nout_shuffled_output   = out[perm]                              # P * SA(X)\n\ndiff = np.abs(out_shuffled_input - out_shuffled_output).max()\nprint(f\"max |SA(PX) - P*SA(X)| = {diff:.2e}   <- zero up to float precision\")\nprint(\"\\n-> Order is simply not in the mechanism.\")\nprint(\"   Fix: add a positional encoding to the input (Part 4).\")","lines":[{"from":1,"to":1,"say":"다섯 자리를 섞는 순서표를 만들어요."},{"from":3,"to":3,"say":"섞은 입력으로 **셀프 어텐션(Self-Attention)** 을 해요. 주석의 SA(PX) 예요."},{"from":4,"to":4,"say":"앞에서 구한 출력을 같은 순서로 섞어요. 주석의 P x SA(X) 예요."},{"from":6,"to":6,"say":"두 결과의 차이를 절댓값으로 재서 가장 큰 값을 구해요."},{"from":7,"to":7,"say":"그 값을 지수 표기로 출력해요. 주석처럼 소수 오차 수준의 0 이에요."},{"from":8,"to":9,"say":"순서는 장치 안에 없고, 고치는 방법은 입력에 **위치 인코딩(Positional Encoding)** 을 더하는 것이라고 알려 줘요."}],"link":"강의 N4 p.40 Barrier 1 - Positional Encoding"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`max |SA(PX) - P*SA(X)| = 1.33e-15   <- zero up to float precision`","`-> Order is simply not in the mechanism.`","`Fix: add a positional encoding to the input (Part 4).`"]},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 셀프 어텐션에는 부족한 정보와 배리어가 있어요.","이 배리어 3개를 기억해 봅시다. 첫 번째는 순서 정보가 없다는 거예요.","병렬로 바꿨는데 그만큼 순서가 상관없어져 버린 겁니다."]}],"pass4":[{"kind":"check","q":"차이가 1.33e-15 로 나왔다는 뜻은?","choices":["사실상 0, 곧 두 결과가 같다는 뜻","오차가 크다는 뜻","계산이 틀렸다는 뜻","1.33 이라는 뜻"],"a":0,"why":"e-15 는 소수점 아래 15째 자리라는 뜻이에요. 컴퓨터가 소수를 다루며 생기는 티끌이에요."},{"kind":"warn","head":"헷갈리는 점","items":["'순서를 모른다' 는 '순서를 무시한다' 가 아니라 '섞으면 출력도 같이 섞인다' 예요.","고치는 자리는 어텐션 계산 안이 아니라 입력이에요. 첫 층 전에 위치 벡터를 더해요."]}]},{"p":10,"title":"2.2 장벽 2: 어텐션은 평균만 낼 수 있어요","terms":["Attention Weight","Position-wise Feed-Forward Network (FFN)","Value","Weighted Sum","Attention"],"pass1":[{"kind":"say","lines":["**어텐션 가중치(Attention Weight)** 는 0 이상이고 합이 1 이에요.","그래서 출력은 늘 **밸류(Value)** 들 사이 어딘가에 있어요. 밖으로 못 나가요."]},{"kind":"analogy","head":"평균의 한계","scene":"반 친구들 키를 아무리 잘 섞어 평균 내도, 반에서 가장 큰 키보다 큰 값은 절대 안 나와요.","map":[["친구들 키","**밸류(Value)** 들"],["섞는 비율","**어텐션 가중치(Attention Weight)**"],["절대 못 넘는 최댓값","볼록 결합의 한계"],["새 값을 만들려면","**위치별 피드포워드 신경망(FFN)**"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**attention can only average, never leave the hull** = 어텐션은 평균만 낼 뿐, 범위를 벗어나지 못해요.","**a convex combination of the value vectors** = 밸류 벡터들의 볼록 결합이에요.","**Attention MOVES information. The feed-forward layer TRANSFORMS it.** = 어텐션은 정보를 옮기고, 피드포워드 층은 정보를 바꿔요."]},{"kind":"pyterm","name":"비교와 & 그리고 .all()","say":["`out >= V.min(axis=0)` 은 칸마다 참/거짓 표를 만들어요.","`&` 는 '둘 다 참' 이고, `.all()` 은 '전부 참인가' 를 묻어요.","`1e-9` 는 0.000000001 이에요. 소수 오차를 눈감아 주는 여유예요."],"example":"import numpy as np\nprint((np.array([1., 2.]) > 0).all())","out":"True"},{"kind":"pyterm","name":"bool() 로 보기 좋게","say":["NumPy 의 참/거짓은 np.True_ 처럼 찍혀요. `bool(...)` 로 감싸면 True 로 깔끔하게 나와요."],"example":"import numpy as np\nprint(bool(np.array([True, True]).all()))","out":"True"}],"pass3":[{"kind":"code","head":"가중치와 출력의 성질 확인","file":"Lab3 노트북 셀 17","code":"V = X @ Wv\ninside = ((out >= V.min(axis=0) - 1e-9) & (out <= V.max(axis=0) + 1e-9)).all()\nprint(\"all attention weights >= 0 :\", bool((A >= 0).all()))\nprint(\"every row sums to 1        :\", bool(np.allclose(A.sum(1), 1)))\nprint(\"every output stays inside [min V, max V] per dimension :\", bool(inside))\nprint(\"\\n-> Attention MOVES information. The feed-forward layer TRANSFORMS it.\")","lines":[{"from":1,"to":1,"say":"**밸류(Value)** 행렬 V 를 다시 만들어요. X 에 Wv 를 곱한 것이에요."},{"from":2,"to":2,"say":"출력이 칸마다 V 의 최솟값과 최댓값 사이에 있는지 한 번에 확인해요."},{"from":3,"to":4,"say":"**어텐션 가중치(Attention Weight)** 가 모두 0 이상인지, 행 합이 1 인지 출력해요."},{"from":5,"to":5,"say":"출력이 밸류가 만드는 범위 안에 있는지 출력해요."},{"from":6,"to":6,"say":"어텐션은 정보를 옮기고 피드포워드 층은 정보를 바꾼다고 알려 줘요."}],"link":"강의 N4 p.42 Barrier 2 - The Feed-Forward Layer"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`all attention weights >= 0 : True`","`every row sums to 1        : True`","`every output stays inside [min V, max V] per dimension : True`","`-> Attention MOVES information. The feed-forward layer TRANSFORMS it.`"]},{"kind":"points","head":"세 줄이 증명한 것","items":["가중치가 음수가 아니고 합이 1 이면 출력은 **가중합(Weighted Sum)** 이 아니라 가중 '평균' 이에요.","평균은 재료들의 범위를 벗어나지 못해요. 어텐션을 더 쌓아도 마찬가지예요.","그래서 **트랜스포머(Transformer)** 에는 **위치별 피드포워드 신경망(FFN)** 이 꼭 있어야 해요."]}],"pass4":[{"kind":"check","q":"어텐션을 여러 층 쌓으면 밸류 범위를 벗어날 수 있나요?","choices":["아니요. 평균의 평균도 여전히 평균이에요","네, 두 층부터 벗어나요","**소프트맥스(Softmax)** 를 빼면 가능해요","**키(Key)** 를 늘리면 가능해요"],"a":0,"why":"그래서 강의가 **위치별 피드포워드 신경망(FFN)** 을 장벽 2 의 처방으로 내놓았어요."},{"kind":"warn","head":"헷갈리는 점","items":["'평균만 낸다' 는 어텐션이 쓸모없다는 뜻이 아니에요. 정보를 옮기는 일은 어텐션이 제일 잘해요.","FFN 은 자리마다 따로 걸려요. 여기서는 토큰끼리 섞이지 않아요."]}]},{"p":11,"title":"2.3 장벽 3: 미래 가리기와 순서의 함정","terms":["Causal Masking","Softmax","Attention Weight","Autoregressive","Language Model (LM)"],"pass1":[{"kind":"say","lines":["**언어 모델(Language Model)** 에서 토큰 i 는 자기 뒤 토큰을 보면 안 돼요.","안 그러면 정답을 미리 보는 셈이라 아무것도 못 배워요.","그래서 그 자리의 점수를 **소프트맥스(Softmax)** 전에 음의 무한대로 만들어요."]},{"kind":"analogy","head":"시험지 가리개","scene":"시험을 볼 때 뒷장을 종이로 덮어 두는 것과 같아요. 답을 다 채운 뒤 걷으면 이미 늦어요.","map":[["뒷장 덮기","**인과 마스킹(Causal Masking)**"],["덮는 시점이 먼저","**소프트맥스(Softmax)** 전에 가리기"],["다 푼 뒤 지우기","소프트맥스 뒤에 0 으로 만드는 흔한 버그"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**masking the future** = 미래를 가리기.","**token i must not see tokens j > i** = 토큰 i 는 자기보다 뒤인 j 를 보면 안 돼요.","**We set those scores to minus infinity before the softmax** = 그 점수를 소프트맥스 전에 음의 무한대로 둬요.","**A very common bug is to zero the weights after the softmax** = 소프트맥스 뒤에 0 으로 만드는 것이 아주 흔한 버그예요."]},{"kind":"pyterm","name":"np.tril 과 == 1","say":["`np.tril(np.ones((n, n)))` 은 아래쪽 삼각형만 1 인 표를 만들어요.","`== 1` 을 붙이면 참/거짓 표가 돼요. 참인 자리만 볼 수 있어요."],"example":"import numpy as np\nprint(np.tril(np.ones((2, 2))))","out":"[[1. 0.]\n [1. 1.]]"},{"kind":"pyterm","name":"물결표 ~ 는 반대","say":["`~causal` 은 참과 거짓을 뒤집어요. 곧 '볼 수 없는 자리' 예요.","`A_masked[~causal].max()` 는 미래 자리에 남은 가장 큰 가중치를 봐요."],"example":"import numpy as np\nprint(~np.array([True, False]))","out":"[False  True]"},{"kind":"pyterm","name":"표끼리 곱하기","say":["`A * causal` 은 같은 자리끼리 곱해요. 거짓(0)인 자리는 0 이 돼요.","이게 바로 노트북이 말하는 '흔한 버그' 를 재현하는 줄이에요."],"example":"import numpy as np\nprint(np.array([0.5, 0.5]) * np.array([1, 0]))","out":"[0.5 0. ]"}],"pass3":[{"kind":"code","head":"올바른 마스킹과 틀린 마스킹","file":"Lab3 노트북 셀 19","code":"causal = np.tril(np.ones((n, n))) == 1          # True where a token may look\n\nout_masked, A_masked = self_attention(X, Wq, Wk, Wv, mask=causal)\n\nprint(\"RIGHT -- mask before softmax:\")\nprint(np.round(A_masked, 2))\nprint(\"row sums:\", np.round(A_masked.sum(1), 6), \" <- still 1\")\nprint(\"max weight on the future:\", A_masked[~causal].max())\n\nA_wrong = A * causal                             # zero them out AFTER softmax\nprint(\"\\nWRONG -- zero out after softmax:\")\nprint(\"row sums:\", np.round(A_wrong.sum(1), 3), \" <- not 1 any more!\")","lines":[{"from":1,"to":1,"say":"아래쪽 삼각형만 참인 표를 만들어요. 주석처럼 참인 자리만 볼 수 있어요."},{"from":3,"to":3,"say":"그 표를 마스크로 넘겨 **셀프 어텐션(Self-Attention)** 을 다시 해요."},{"from":5,"to":7,"say":"올바른 방식의 어텐션 행렬과 행 합을 출력해요. 행 합은 여전히 1 이에요."},{"from":8,"to":8,"say":"미래 자리에 남은 가장 큰 **어텐션 가중치(Attention Weight)** 를 출력해요. 0.0 이어야 해요."},{"from":10,"to":10,"say":"틀린 방식이에요. **소프트맥스(Softmax)** 를 건 뒤에 미래 자리를 0 으로 눌러요."},{"from":11,"to":12,"say":"그 결과의 행 합을 출력해요. 더 이상 1 이 아니에요."}],"link":"강의 N4 p.43 Barrier 3 - Masking the Future"},{"kind":"points","head":"저장된 출력 1: 올바른 마스킹","items":["`RIGHT -- mask before softmax:`","`[[1.   0.   0.   0.   0.  ]`","`[0.01 0.99 0.   0.   0.  ]`","`[0.12 0.17 0.71 0.   0.  ]`","`[0.05 0.88 0.01 0.06 0.  ]`","`[0.15 0.25 0.09 0.31 0.2 ]]`","`row sums: [1. 1. 1. 1. 1.]  <- still 1`","`max weight on the future: 0.0`"]},{"kind":"points","head":"저장된 출력 2: 틀린 마스킹","items":["`WRONG -- zero out after softmax:`","`row sums: [0.054 0.761 0.529 0.97  1.   ]  <- not 1 any more!`"]},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 마이너스 무한대는 익스포넨셜을 치면 0 에 가까운 수가 되죠.","그래서 **인과 마스킹(Causal Masking)** 은 점수를 마이너스 무한으로 만들어서","모델이 아직 보지 말아야 할 미래 토큰 정보를 완전히 차단하는 겁니다."]}],"pass4":[{"kind":"check","q":"**소프트맥스(Softmax)** 뒤에 가중치를 0 으로 만들면 무엇이 깨지나요?","choices":["행의 합이 1 이 아니게 돼서 더 이상 가중 평균이 아니에요","점수가 음수가 돼요","**밸류(Value)** 가 바뀌어요","아무 문제 없어요"],"a":0,"why":"출력 행 합이 [0.054, 0.761, 0.529, 0.97, 1.0] 로 제각각이에요. 남은 가중치를 다시 나눠 주지 않았거든요."},{"kind":"warn","head":"시험에 나오기 좋은 점","items":["마스크는 반드시 **소프트맥스(Softmax)** 앞에 걸어요. 강의 Check Yourself 2번 문제예요.","첫 행이 [1, 0, 0, 0, 0] 인 것은 첫 토큰이 자기 자신밖에 볼 게 없어서예요.","인코더는 이 마스크를 쓰지 않고 양쪽을 다 봐요. **자기회귀(Autoregressive)** 모델만 써요."]},{"kind":"check","q":"**인과 마스킹(Causal Masking)** 이 꼭 필요한 모델은?","choices":["**자기회귀(Autoregressive)** **언어 모델(Language Model)**","양쪽을 다 보는 인코더","번역기 인코더","**위치 인코딩(Positional Encoding)**"],"a":0,"why":"다음 토큰을 맞혀야 하는 **언어 모델(Language Model)** 만 미래를 가려요. 인코더는 양쪽을 봐요."}]},{"p":12,"title":"Part 3 PyTorch 로 옮기고 내장 구현과 대조","terms":["Scaled Dot-Product Attention","Tensor","Shape","Causal Masking","Softmax"],"pass1":[{"kind":"say","lines":["같은 식을 이제 PyTorch 로 옮겨요. 그래야 학습을 시킬 수 있어요.","직접 만든 함수를 PyTorch 내장 구현과 맞대 봐요. 1e-6 수준에서 같으면 잘 만든 거예요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Same maths, now in PyTorch so it can be trained** = 같은 수식인데 학습이 되게 PyTorch 로 옮겨요.","**check it against PyTorch's own built-in implementation** = PyTorch 가 이미 갖고 있는 구현과 대조해요.","**if they agree to 1e-6, we got it right** = 1e-6 안에서 같으면 제대로 만든 거예요."]},{"kind":"pyterm","name":"따옴표 세 개 설명문","say":["함수 첫 줄의 `'''...'''` 는 이 함수의 설명이에요. 실행에는 영향이 없어요.","여기서는 q, k, v 의 **모양(Shape)** 이 (묶음, 헤드, 길이, 헤드 차원) 이라고 알려 줘요."],"example":"def f():\n    '''설명'''\n    return 1\nprint(f())","out":"1"},{"kind":"pyterm","name":".transpose(-2, -1)","say":["마지막 두 축만 뒤집어요. (B, H, T, D) 가 (B, H, D, T) 가 돼요.","앞 두 축은 그대로 둬야 묶음과 **헤드(Head)** 가 섞이지 않아요."],"example":"import torch\nprint(tuple(torch.zeros(2, 3, 4, 5).transpose(-2, -1).shape))","out":"(2, 3, 5, 4)"},{"kind":"pyterm","name":"torch.triu 와 masked_fill","say":["`torch.triu(..., diagonal=1)` 은 대각선 위쪽, 곧 미래 자리만 참으로 만들어요.","`scores.masked_fill(future, float(\"-inf\"))` 는 참인 자리를 음의 무한대로 채워요."],"example":"import torch\nprint(torch.triu(torch.ones(2, 2), diagonal=1))","out":"tensor([[0., 1.],\n        [0., 0.]])"},{"kind":"pyterm","name":"F.scaled_dot_product_attention","say":["PyTorch 가 이미 갖고 있는 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)** 이에요.","`is_causal=True` 로 **인과 마스킹(Causal Masking)** 을 켜요. 답을 맞춰 보는 용도로 써요."],"example":"import torch.nn.functional as F"}],"pass3":[{"kind":"code","head":"내가 만든 어텐션 대 PyTorch 내장 어텐션","file":"Lab3 노트북 셀 21","code":"def scaled_dot_product_attention(q, k, v, causal=False):\n    '''q, k, v: (batch, heads, seq, head_dim)'''\n    d_k = q.shape[-1]\n    scores = q @ k.transpose(-2, -1) / math.sqrt(d_k)          # (B, H, T, T)\n    if causal:\n        T = q.shape[-2]\n        future = torch.triu(torch.ones(T, T, dtype=torch.bool), diagonal=1)\n        scores = scores.masked_fill(future, float(\"-inf\"))\n    attn = scores.softmax(dim=-1)\n    return attn @ v, attn\n\nB, T, D, H = 2, 7, 64, 4\nq = torch.randn(B, H, T, D // H)\nk = torch.randn(B, H, T, D // H)\nv = torch.randn(B, H, T, D // H)\n\nours, _ = scaled_dot_product_attention(q, k, v, causal=True)\nref     = F.scaled_dot_product_attention(q, k, v, is_causal=True)   # PyTorch's own\n\nprint(\"ours :\", tuple(ours.shape))\nprint(\"max absolute difference vs PyTorch:\", (ours - ref).abs().max().item())","lines":[{"from":1,"to":2,"say":"함수를 정의하고, 설명문으로 입력 **모양(Shape)** 을 알려 줘요."},{"from":3,"to":3,"say":"키 차원 d_k 를 마지막 축 크기에서 꺼내요."},{"from":4,"to":4,"say":"점수를 구하고 루트 d_k 로 나눠요. 주석처럼 (B, H, T, T) 크기예요."},{"from":5,"to":8,"say":"causal 이 참이면 미래 자리를 찾아 음의 무한대로 채워요."},{"from":9,"to":9,"say":"마지막 축에 **소프트맥스(Softmax)** 를 걸어 가중치를 만들어요."},{"from":10,"to":10,"say":"가중치로 밸류를 섞은 출력과 가중치를 함께 돌려줘요."},{"from":12,"to":12,"say":"묶음 2, 길이 7, 전체 차원 64, **헤드(Head)** 4개로 정해요."},{"from":13,"to":15,"say":"q, k, v 를 (2, 4, 7, 16) 크기 무작위 **텐서(Tensor)** 로 만들어요. 16 은 64 나누기 4 예요."},{"from":17,"to":17,"say":"우리 함수로 계산해요."},{"from":18,"to":18,"say":"PyTorch 내장 함수로 같은 계산을 해요."},{"from":20,"to":21,"say":"우리 결과의 모양과 두 결과의 최대 차이를 출력해요."}],"link":"강의 N4 p.36 The Equations, p.43 마스킹"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`ours : (2, 4, 7, 16)`","`max absolute difference vs PyTorch: 2.384185791015625e-07`"]},{"kind":"steps","head":"모양을 따라가기","steps":["q 는 (2, 4, 7, 16), k 를 눕히면 (2, 4, 16, 7)","둘을 곱하면 (2, 4, 7, 7). 길이 7 짜리 어텐션 행렬이 묶음 2 x 헤드 4 개 생겨요.","거기에 v (2, 4, 7, 16) 을 곱하면 다시 (2, 4, 7, 16)"],"answer":"입력과 출력의 **모양(Shape)** 이 같아요. 그래서 블록을 계속 쌓을 수 있어요."}],"pass4":[{"kind":"check","q":"두 결과의 최대 차이가 2.38e-07 이라는 뜻은?","choices":["소수 표현 오차 수준이라 사실상 같다는 뜻","우리 구현이 틀렸다는 뜻","PyTorch 가 틀렸다는 뜻","차이가 2.38 이라는 뜻"],"a":0,"why":"1e-6 보다 작으면 같다고 봐요. 노트북이 미리 정한 합격선이에요."},{"kind":"warn","head":"헷갈리는 점","items":["우리 함수는 causal, 내장 함수는 is_causal 로 이름이 달라요. 옵션 이름을 틀리면 마스크가 안 걸려요.","float(\"-inf\") 는 음의 무한대예요. 0 을 넣으면 마스킹이 안 돼요."]}]},{"p":13,"title":"3.1 멀티 헤드 셀프 어텐션을 모듈로","terms":["Multi-Head Attention (MHA)","Head","Self-Attention","Shape","Parameter","Tensor"],"pass1":[{"kind":"say","lines":["전체 차원 d 를 **헤드(Head)** h 개로 나눠서 따로 어텐션을 하고, 이어 붙인 뒤 다시 섞어요.","이것이 **멀티 헤드 어텐션(Multi-Head Attention)** 이에요."]},{"kind":"analogy","head":"여러 관점으로 한 문장 보기","scene":"같은 사진을 문법 담당, 가까운 문맥 담당, 뜻 담당이 각각 본 뒤 의견을 모으는 것과 같아요.","map":[["담당자 한 명","**헤드(Head)** 하나"],["담당자 여러 명","**멀티 헤드 어텐션(Multi-Head Attention)**"],["의견 모으기","이어 붙인 뒤 W^O 곱하기"],["일을 나눠 맡기","차원을 d/h 로 쪼개기"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Split d into h heads of size d/h** = d 를 크기 d/h 인 **헤드(Head)** h 개로 나눠요.","**run attention in each independently, concatenate** = 각각 따로 어텐션 하고 이어 붙여요.","**project back with W^O** = 마지막에 출력 행렬로 다시 섞어요.","**One nn.Linear produces Q, K and V at once** = 선형층 하나로 Q, K, V 를 한 번에 만드는 구현 요령이에요."]},{"kind":"pyterm","name":"class 와 nn.Module","say":["`class MultiHeadSelfAttention(nn.Module):` 는 PyTorch 부품을 새로 만들어요.","`__init__` 은 부품을 준비하는 곳, `forward` 는 실제로 계산하는 곳이에요.","`super().__init__()` 은 부모가 준비할 것을 먼저 챙겨 줘요."],"example":"import torch.nn as nn\nclass M(nn.Module):\n    def __init__(self):\n        super().__init__()\nprint(type(M()).__name__)","out":"M"},{"kind":"pyterm","name":"nn.Linear","say":["`nn.Linear(64, 192)` 는 64칸을 192칸으로 바꾸는 학습되는 층이에요.","곱할 행렬과 더할 편향 항이 **파라미터(Parameter)** 예요."],"example":"import torch, torch.nn as nn\nprint(tuple(nn.Linear(64, 192)(torch.zeros(1, 64)).shape))","out":"(1, 192)"},{"kind":"pyterm","name":".view, .transpose, .reshape","say":["`.view(B, T, h, d_head)` 는 숫자는 그대로 두고 **모양(Shape)** 만 바꿔요.","`.transpose(1, 2)` 는 축 1 과 2 를 맞바꿔요. `.reshape` 는 다시 합칠 때 써요."],"example":"import torch\nprint(tuple(torch.zeros(2, 7, 64).view(2, 7, 4, 16).transpose(1, 2).shape))","out":"(2, 4, 7, 16)"},{"kind":"pyterm","name":".split 과 map","say":["`self.qkv(x).split(D, dim=-1)` 은 192칸을 64칸씩 셋으로 잘라요.","`map(self.split_heads, (q, k, v))` 는 세 **텐서(Tensor)** 에 같은 함수를 한 번에 걸어요."],"example":"print(list(map(abs, (-1, -2))))","out":"[1, 2]"},{"kind":"pyterm","name":"assert 와 나머지 연산 %","say":["`d_model % n_heads == 0` 은 나눠떨어지는지 보는 것이에요.","`assert 조건, \"메시지\"` 는 조건이 거짓이면 그 메시지와 함께 멈춰요."],"example":"print(64 % 4, 64 % 5)","out":"0 4"}],"pass3":[{"kind":"code","head":"멀티 헤드 셀프 어텐션 모듈","file":"Lab3 노트북 셀 23","code":"class MultiHeadSelfAttention(nn.Module):\n    def __init__(self, d_model, n_heads, causal=True):\n        super().__init__()\n        assert d_model % n_heads == 0, \"d_model must be divisible by n_heads\"\n        self.h, self.d_head, self.causal = n_heads, d_model // n_heads, causal\n        self.qkv  = nn.Linear(d_model, 3 * d_model)   # W^Q, W^K, W^V in one matrix\n        self.proj = nn.Linear(d_model, d_model)       # W^O\n\n    def split_heads(self, t):                          # (B,T,D) -> (B,h,T,D/h)\n        B, T, D = t.shape\n        return t.view(B, T, self.h, self.d_head).transpose(1, 2)\n\n    def forward(self, x):\n        B, T, D = x.shape\n        q, k, v = self.qkv(x).split(D, dim=-1)\n        q, k, v = map(self.split_heads, (q, k, v))\n        out, attn = scaled_dot_product_attention(q, k, v, causal=self.causal)\n        out = out.transpose(1, 2).reshape(B, T, D)     # concat the heads back\n        self.last_attn = attn.detach()                 # keep it so we can look at it\n        return self.proj(out)\n\nmha = MultiHeadSelfAttention(d_model=64, n_heads=4)\nx   = torch.randn(2, 7, 64)\ny   = mha(x)\nprint(\"input  :\", tuple(x.shape))\nprint(\"output :\", tuple(y.shape), \" <- same shape in, same shape out\")\nprint(\"attn   :\", tuple(mha.last_attn.shape), \" (batch, heads, query, key)\")","lines":[{"from":1,"to":3,"say":"새 부품을 정의하고, 만들 때 전체 차원, **헤드(Head)** 수, 마스크 여부를 받아요."},{"from":4,"to":4,"say":"전체 차원이 헤드 수로 나눠떨어지는지 먼저 확인해요."},{"from":5,"to":5,"say":"헤드 수, 헤드 하나의 차원(d/h), 마스크 여부를 저장해요."},{"from":6,"to":6,"say":"선형층 하나로 Q, K, V 를 한 번에 만들어요. 주석처럼 세 행렬을 한 행렬에 넣은 거예요."},{"from":7,"to":7,"say":"헤드를 합친 뒤 다시 섞어 줄 출력 행렬 W^O 예요."},{"from":9,"to":11,"say":"(B, T, D) 를 (B, h, T, D/h) 로 바꾸는 함수예요. 주석에 모양 변화가 적혀 있어요."},{"from":13,"to":14,"say":"실제 계산이에요. 입력의 묶음 수, 길이, 차원을 꺼내요."},{"from":15,"to":15,"say":"한 번에 만든 192칸을 64칸씩 q, k, v 로 잘라요."},{"from":16,"to":16,"say":"셋 모두 **헤드(Head)** 별로 쪼개요."},{"from":17,"to":17,"say":"앞 쪽에서 만든 **스케일드 닷프로덕트 어텐션(Scaled Dot-Product Attention)** 을 불러요."},{"from":18,"to":18,"say":"헤드를 다시 이어 붙여 (B, T, D) 로 돌려놔요."},{"from":19,"to":19,"say":"나중에 그림으로 보려고 **어텐션 가중치(Attention Weight)** 를 따로 보관해요."},{"from":20,"to":20,"say":"출력 행렬을 곱해 돌려줘요."},{"from":22,"to":24,"say":"차원 64, 헤드 4개짜리 모듈을 만들고 (2, 7, 64) 입력을 넣어요."},{"from":25,"to":27,"say":"입력, 출력, 어텐션의 **모양(Shape)** 을 출력해요."}],"link":"강의 N4 p.47 Multi-Head Attention"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`input  : (2, 7, 64)`","`output : (2, 7, 64)  <- same shape in, same shape out`","`attn   : (2, 4, 7, 7)  (batch, heads, query, key)`"]},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 헤드는 그야말로 어텐션을 보는 행위 하나입니다.","헤드 1은 문법적인 관계, 헤드 2는 가까운 문맥, 헤드 3은 의미의 뜻을 보겠다,","이렇게 각 헤드가 서로 다른 Wq, Wk, Wv 를 씁니다."]}],"pass4":[{"kind":"check","q":"입력이 (2, 7, 64) 인데 출력도 (2, 7, 64) 인 까닭은?","choices":["헤드를 다시 이어 붙이고 W^O 로 섞어 원래 차원으로 돌려놓기 때문","**헤드(Head)** 가 4개라서","**소프트맥스(Softmax)** 때문","무작위라서"],"a":0,"why":"모양이 그대로여야 블록을 몇 층이든 쌓을 수 있어요. 노트북 주석도 같은 모양 들어가 같은 모양 나온다고 해요."},{"kind":"warn","head":"헷갈리는 점","items":["attn 의 **모양(Shape)** 은 (묶음, 헤드, 쿼리, 키) 예요. (2, 4, 7, 7) 의 마지막 두 7 을 바꿔 읽으면 안 돼요.","`self.qkv` 의 출력이 3 x 64 = 192 칸인 것은 Q, K, V 를 한 층에 몰아넣었기 때문이에요."]}]},{"p":14,"title":"3.2 헤드를 늘려도 공짜인지 세어 보기","terms":["Multi-Head Attention (MHA)","Head","Parameter"],"pass1":[{"kind":"say","lines":["강의는 **헤드(Head)** 가 d/h 차원만 쓰니까 h 개를 써도 비용이 같다고 했어요.","**파라미터(Parameter)** 개수를 직접 세어 확인해요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**h heads really are free** = 헤드 h 개는 정말 공짜예요.","**Count the parameters and see** = 파라미터를 세어서 확인해 보세요.","**h different views of the sentence, at no extra cost** = 추가 비용 없이 문장을 h 가지 관점으로 봐요."]},{"kind":"pyterm","name":".parameters() 와 .numel()","say":["`m.parameters()` 는 모델 안의 학습되는 숫자 묶음을 모두 꺼내요.","`p.numel()` 은 그 묶음에 숫자가 몇 개인지예요.","`sum(p.numel() for p in m.parameters())` 가 전체 **파라미터(Parameter)** 수예요."],"example":"import torch.nn as nn\nprint(sum(p.numel() for p in nn.Linear(2, 3).parameters()))","out":"9"},{"kind":"pyterm","name":"천 단위 쉼표 서식","say":["`f\"{16640:,}\"` 은 16,640 처럼 세 자리마다 쉼표를 넣어요.","`{h:>8}` 은 오른쪽으로 8칸 맞춰 표처럼 보이게 해요."],"example":"print(f\"{16640:,}\")","out":"16,640"}],"pass3":[{"kind":"code","head":"헤드 수만 바꿔 가며 파라미터 세기","file":"Lab3 노트북 셀 25","code":"print(\" n_heads   parameters\")\nfor h in (1, 2, 4, 8, 16):\n    m = MultiHeadSelfAttention(d_model=64, n_heads=h)\n    print(f\"{h:>8}   {sum(p.numel() for p in m.parameters()):>10,}\")\nprint(\"\\n-> identical. h different views of the sentence, at no extra cost.\")","lines":[{"from":1,"to":1,"say":"표의 머리글을 출력해요."},{"from":2,"to":2,"say":"**헤드(Head)** 를 1, 2, 4, 8, 16 개로 바꿔 가며 돌아요."},{"from":3,"to":3,"say":"그때마다 차원 64 짜리 모듈을 새로 만들어요."},{"from":4,"to":4,"say":"그 모듈의 **파라미터(Parameter)** 개수를 모두 더해 출력해요."},{"from":5,"to":5,"say":"값이 전부 같다고, 곧 h 가지 관점이 추가 비용 없이 공짜라고 알려 줘요."}],"link":"강의 N4 p.48 Multi-Head Costs Nothing Extra"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`n_heads   parameters`","`1       16,640`","`2       16,640`","`4       16,640`","`8       16,640`","`16       16,640`"]},{"kind":"steps","head":"16,640 을 손으로 세기","steps":["qkv 층: 64칸을 192칸으로. 곱할 행렬 64 x 192 = 12,288","거기에 편향 항 192 개를 더하면 12,480","출력 층 W^O: 64 x 64 = 4,096 에 편향 항 64 개를 더해 4,160","12,480 + 4,160 = 16,640"],"answer":"**헤드(Head)** 수는 이 계산 어디에도 안 나와요. 그래서 h 를 바꿔도 값이 같아요."},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 헤드를 여러 개 쓴다고 전체 차원을 키우는 게 아니라","전체 차원을 h 로 나눠서 서로 다른 관점에서 보는 겁니다.","그래서 멀티 헤드라고 헤드를 여러 번 했을 때 계산량이 더 많아지는 건 아니에요."]}],"pass4":[{"kind":"check","q":"**헤드(Head)** 를 1개에서 16개로 늘렸는데 **파라미터(Parameter)** 가 그대로인 까닭은?","choices":["헤드마다 쓰는 차원이 64/h 로 줄어들기 때문","PyTorch 가 아껴 주기 때문","**소프트맥스(Softmax)** 때문","편향 항이 없기 때문"],"a":0,"why":"쪼개서 나눠 쓰는 것이지 더 붙이는 게 아니에요. 교수님이 강조한 부분이에요."},{"kind":"english","head":"답안 문장","en":"멀티 헤드 어텐션은 전체 차원 d 를 헤드 수 h 로 나눈 d/h 차원 부분공간에서 어텐션을 각각 수행한 뒤 이어 붙여 출력 행렬로 사영하므로, 파라미터 수와 계산량은 헤드 하나일 때와 같다.","ko":"차원을 키우는 게 아니라 쪼개는 것이라서 비용이 같아요. 실습에서 16,640 으로 확인했어요.","tip":"'쪼개는 것이지 붙이는 게 아니다' 한 줄로 외워요."},{"kind":"warn","head":"헷갈리는 점","items":["'공짜' 는 **파라미터(Parameter)** 와 계산량 이야기예요. 성능이 늘 좋아진다는 뜻은 아니에요.","64 를 16 으로 나누면 헤드마다 4칸뿐이에요. 너무 잘게 쪼개면 헤드 하나가 볼 게 적어져요."]}]},{"p":15,"title":"Part 4 시작: 위치 인코딩과 Pre-LN 블록","terms":["Positional Encoding","Sinusoidal Positional Encoding","Residual Connection","Layer Normalization (LayerNorm)","Transformer","Position-wise Feed-Forward Network (FFN)"],"pass1":[{"kind":"say","lines":["이제 전부 조립해요. **위치 인코딩(Positional Encoding)** 을 더하고,","어텐션과 **위치별 피드포워드 신경망(FFN)** 을 **잔차 연결(Residual Connection)** 로 잇고,","**층 정규화(Layer Normalization)** 를 앞에 두는 Pre-LN 블록을 쌓아요."]},{"kind":"points","head":"Part 4 에서 할 일","items":["4.1 **사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 만들고 그림으로 보기","4.2 **트랜스포머(Transformer)** 블록과 미니 모델 조립하기","4.3 어텐션이 보이는 과제로 실제 학습시키기","4.4 어텐션 그림 읽기, 4.5 장벽 세 개를 실험으로 확인하기"]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**positional encoding + Pre-LN block** = 위치 인코딩과 층 정규화를 앞에 둔 블록.","**attention → FFN, each with a residual** = 어텐션 다음 **위치별 피드포워드 신경망(FFN)**, 각각 **잔차 연결(Residual Connection)** 을 달고.","**The heatmap looks striped** = 히트맵이 줄무늬처럼 보여요.","**a sin/cos pair of the same frequency** = 이웃한 두 열이 같은 주파수의 사인, 코사인 쌍이에요.","**Low dimensions turn fast, high dimensions turn slowly** = 낮은 차원은 빨리, 높은 차원은 천천히 돌아요."]},{"kind":"points","head":"왜 줄무늬가 보이나","items":["차원 0 과 1 이 같은 파장, 차원 2 와 3 이 그다음 파장을 써요.","그래서 이웃한 두 열이 비슷하게 보이고 줄무늬처럼 나타나요.","위치마다 64칸 전체의 무늬가 달라서 자리를 구별할 수 있어요."]}],"pass3":[{"kind":"points","head":"강의와 짝","items":["N4 p.40 Barrier 1 이 **위치 인코딩(Positional Encoding)** 이에요.","N4 p.49 가 **잔차 연결(Residual Connection)**, N4 p.50 이 **층 정규화(Layer Normalization)** 예요.","N4 p.51 Pre-LN or Post-LN 이 이 노트북이 고른 배치예요. 요즘 LLM 은 전부 Pre-LN 이에요."]}],"pass4":[{"kind":"check","q":"**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 의 히트맵이 줄무늬인 까닭은?","choices":["이웃한 두 열이 같은 파장의 사인, 코사인 쌍이라서","무작위라서","**헤드(Head)** 가 여러 개라서","학습이 덜 돼서"],"a":0,"why":"차원 0 과 1 이 한 쌍, 2 와 3 이 다음 쌍이에요. 그래서 옆 열끼리 닮아 보여요."},{"kind":"warn","head":"헷갈리는 점","items":["**층 정규화(Layer Normalization)** 는 토큰 하나 안에서만 고르게 만들어요. 토큰끼리 섞지 않아요.","Pre-LN 은 **잔차 연결(Residual Connection)** 길을 깨끗이 남겨 둬서 깊게 쌓아도 학습이 돼요."]}]},{"p":16,"title":"4.1 사인 코사인 위치 인코딩 만들기","terms":["Sinusoidal Positional Encoding","Positional Encoding","Tensor","Shape","Permutation Equivariance"],"pass1":[{"kind":"say","lines":["자리마다 다른 물결 무늬 벡터를 만들어요.","이걸 토큰 벡터에 더하면 **셀프 어텐션(Self-Attention)** 도 순서를 알게 돼요."]}],"pass2":[{"kind":"points","head":"무엇을 만드나","items":["**모양(Shape)** 이 (60, 64) 인 표예요. 자리 60개, 차원 64칸.","짝수 칸은 사인, 홀수 칸은 코사인으로 채워요.","파장이 차원마다 달라서 자리마다 고유한 무늬가 생겨요."]},{"kind":"pyterm","name":"torch.zeros 와 torch.arange","say":["`torch.zeros(60, 64)` 는 0 으로 채운 60행 64열 **텐서(Tensor)** 예요.","`torch.arange(60)` 은 0, 1, 2, ... 59 를 만들어요.","`.unsqueeze(1)` 은 칸 하나를 끼워 넣어 (60,) 을 (60, 1) 로 만들어요."],"example":"import torch\nprint(tuple(torch.arange(3).unsqueeze(1).shape))","out":"(3, 1)"},{"kind":"pyterm","name":"건너뛰며 고르는 [:, 0::2]","say":["`pe[:, 0::2]` 는 모든 행의 0, 2, 4, ... 번째 열, 곧 짝수 칸이에요.","`pe[:, 1::2]` 는 홀수 칸이에요. 사인과 코사인을 번갈아 넣으려고 써요."],"example":"import torch\nprint(torch.arange(6)[0::2])","out":"tensor([0, 2, 4])"},{"kind":"pyterm","name":"torch.pow 와 나눗셈 방송","say":["`torch.pow(10000.0, ...)` 은 10000 의 거듭제곱이에요. 칸마다 파장이 달라져요.","`pos / div` 는 (60, 1) 과 (32,) 가 만나 (60, 32) 가 돼요. 모양이 자동으로 맞춰져요."],"example":"import torch\nprint(tuple((torch.zeros(60, 1) / torch.zeros(32)).shape))","out":"(60, 32)"},{"kind":"pyterm","name":"plt.subplots 와 imshow","say":["`plt.subplots(1, 2, ...)` 는 그림 하나에 그래프 칸 두 개를 만들어요.","`imshow` 는 숫자 표를 색으로 칠한 히트맵이에요. `plt.show()` 로 화면에 띄워요."],"example":"import matplotlib.pyplot as plt"}],"pass3":[{"kind":"formula","head":"사인 코사인 위치 인코딩","tex":"PE_{(pos,2i)}=\\sin\\!\\left(\\frac{pos}{10000^{2i/d}}\\right),\\quad PE_{(pos,2i+1)}=\\cos\\!\\left(\\frac{pos}{10000^{2i/d}}\\right)","parts":[{"sym":"pos","say":"몇 번째 자리인지"},{"sym":"2i,\\,2i+1","say":"짝수 칸은 사인, 홀수 칸은 코사인"},{"sym":"10000^{2i/d}","say":"칸마다 다른 파장. 뒤 칸일수록 천천히 돌아요"}],"whole":"학습할 **파라미터(Parameter)** 가 하나도 없어요. 식으로 바로 계산해요."},{"kind":"code","head":"위치 인코딩 표 만들고 그림 그리기","file":"Lab3 노트북 셀 27","code":"def sinusoidal_pe(max_len, d_model):\n    pe  = torch.zeros(max_len, d_model)\n    pos = torch.arange(max_len).unsqueeze(1).float()\n    div = torch.pow(10000.0, torch.arange(0, d_model, 2).float() / d_model)\n    pe[:, 0::2] = torch.sin(pos / div)\n    pe[:, 1::2] = torch.cos(pos / div)\n    return pe\n\npe = sinusoidal_pe(60, 64)\nfig, ax = plt.subplots(1, 2, figsize=(11, 2.8))\nim = ax[0].imshow(pe, aspect=\"auto\", cmap=\"RdBu_r\", vmin=-1, vmax=1)\nax[0].set_xlabel(\"dimension\"); ax[0].set_ylabel(\"position\")\nax[0].set_title(\"sinusoidal positional encoding\"); fig.colorbar(im, ax=ax[0])\nfor dim, c in [(0, \"tab:red\"), (8, \"tab:blue\"), (24, \"tab:green\")]:\n    ax[1].plot(pe[:, dim], color=c, label=f\"dim {dim}\")\nax[1].legend(); ax[1].set_xlabel(\"position\")\nax[1].set_title(\"each dimension is a wave of its own wavelength\")\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":1,"say":"자리 수와 차원 수를 받아 **위치 인코딩(Positional Encoding)** 표를 만드는 함수예요."},{"from":2,"to":2,"say":"0 으로 채운 (자리 수, 차원) 표를 준비해요."},{"from":3,"to":3,"say":"0부터 자리 수 - 1 까지 번호를 세로로 세워요."},{"from":4,"to":4,"say":"칸마다 다른 파장을 계산해요. 10000 의 거듭제곱이에요."},{"from":5,"to":6,"say":"짝수 칸은 사인, 홀수 칸은 코사인으로 채워요."},{"from":7,"to":7,"say":"완성한 표를 돌려줘요."},{"from":9,"to":9,"say":"자리 60개, 차원 64칸짜리 표를 만들어요."},{"from":10,"to":10,"say":"그림 칸 두 개를 준비해요."},{"from":11,"to":13,"say":"왼쪽 칸에 표 전체를 히트맵으로 칠하고, 축 이름과 제목, 색 막대를 붙여요."},{"from":14,"to":15,"say":"오른쪽 칸에 차원 0, 8, 24 세 개를 물결 곡선으로 그려요."},{"from":16,"to":17,"say":"범례와 축 이름, 제목을 붙여요."},{"from":18,"to":18,"say":"여백을 정리하고 화면에 띄워요."}],"link":"강의 N4 p.40 sinusoids of geometrically spaced frequencies"},{"kind":"points","head":"저장된 출력","items":["`<Figure size 1100x280 with 3 Axes>` 와 그림이 나와요. 숫자 출력은 없어요.","왼쪽 히트맵은 줄무늬, 오른쪽은 차원마다 파장이 다른 물결 곡선이에요.","차원 0 은 빠르게, 차원 24 는 아주 천천히 돌아요."]},{"kind":"steps","head":"맨 첫 자리를 손으로","steps":["pos = 0 이면 사인은 sin(0) = 0","코사인은 cos(0) = 1","그래서 0번 자리 벡터는 0, 1, 0, 1, ... 이 돼요.","pos = 1 이면 칸마다 조금씩 다른 값이 나와요."],"answer":"자리마다 64칸 무늬가 달라서, 같은 단어라도 자리가 다르면 벡터가 달라져요."}],"pass4":[{"kind":"check","q":"**위치 인코딩(Positional Encoding)** 을 토큰 벡터에 더하는 까닭은?","choices":["**순열 등변성(Permutation Equivariance)** 때문에 순서를 입력에 넣어 줘야 해서","학습을 빠르게 하려고","**파라미터(Parameter)** 를 줄이려고","**소프트맥스(Softmax)** 를 위해"],"a":0,"why":"2.1 에서 잰 그대로예요. 순서가 계산 안에 없으니 입력에 넣어 줘요."},{"kind":"warn","head":"헷갈리는 점","items":["더하는 것이지 이어 붙이는 게 아니에요. 차원이 늘지 않아요.","**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 은 학습하지 않아요. 요즘 LLM 은 RoPE 를 더 많이 써요."]}]},{"p":17,"title":"4.2 트랜스포머 블록과 미니 모델 조립","terms":["Transformer","Residual Connection","Identity Path","Layer Normalization (LayerNorm)","Position-wise Feed-Forward Network (FFN)","Multi-Head Attention (MHA)","Embedding","Sinusoidal Positional Encoding","Parameter","Shape","Gradient"],"pass1":[{"kind":"say","lines":["드디어 **트랜스포머(Transformer)** 블록을 조립해요.","두 줄이면 끝이에요. x = x + 어텐션(정규화(x)), 그다음 x = x + FFN(정규화(x))."]},{"kind":"analogy","head":"블록은 두 칸짜리 공정","scene":"공장 라인 같아요. 첫 칸에서 부품을 옮겨 오고, 둘째 칸에서 그 부품을 가공해요. 원래 물건은 옆 컨베이어로 같이 흘러가요.","map":[["옮겨 오는 칸","**멀티 헤드 어텐션(Multi-Head Attention)**"],["가공하는 칸","**위치별 피드포워드 신경망(FFN)**"],["옆 컨베이어","**잔차 연결(Residual Connection)**"],["들어가기 전 줄 맞추기","**층 정규화(Layer Normalization)**"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**x = x + Attention(LN(x))** = 정규화한 뒤 어텐션을 걸고, 원래 x 에 더해요.","**x = x + FFN(LN(x))** = 정규화한 뒤 FFN 을 걸고, 다시 원래 x 에 더해요.","**the Pre-LN arrangement from the lecture** = 강의에서 본 Pre-LN 배치예요.","**which is what every modern LLM uses** = 요즘 LLM 은 전부 이 배치를 써요."]},{"kind":"pyterm","name":"nn.LayerNorm","say":["`nn.LayerNorm(64)` 는 토큰 한 개의 64칸을 평균 0, 분산 1 로 고르게 만들어요.","**층 정규화(Layer Normalization)** 는 토큰끼리 섞지 않아요. 배치 크기와도 상관없어요."],"example":"import torch, torch.nn as nn\nprint(tuple(nn.LayerNorm(4)(torch.zeros(2, 4)).shape))","out":"(2, 4)"},{"kind":"pyterm","name":"nn.Sequential 과 nn.GELU","say":["`nn.Sequential(a, b, c)` 는 부품을 차례로 통과시키는 묶음이에요.","`nn.GELU()` 는 ReLU 를 부드럽게 만든 활성화 함수예요. 비선형을 넣어 줘요."],"example":"import torch, torch.nn as nn\nm = nn.Sequential(nn.Linear(4, 8), nn.GELU(), nn.Linear(8, 4))\nprint(tuple(m(torch.zeros(1, 4)).shape))","out":"(1, 4)"},{"kind":"pyterm","name":"nn.Embedding","say":["`nn.Embedding(11, 64)` 은 토큰 11종류마다 64칸 벡터를 하나씩 가진 표예요.","번호를 넣으면 그 줄을 꺼내 줘요. 이것이 **임베딩(Embedding)** 이에요."],"example":"import torch, torch.nn as nn\nprint(tuple(nn.Embedding(11, 64)(torch.tensor([0, 3])).shape))","out":"(2, 64)"},{"kind":"pyterm","name":"register_buffer 와 nn.ModuleList","say":["`register_buffer(\"pe\", ...)` 는 학습하지 않는 값을 모델에 붙여 둬요.","**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 은 학습이 필요 없어서 여기에 넣어요.","`nn.ModuleList([...])` 는 블록 여러 개를 줄 세워 담는 통이에요."],"example":"import torch.nn as nn\nprint(len(nn.ModuleList([nn.Linear(2, 2) for _ in range(3)])))","out":"3"},{"kind":"pyterm","name":"for 안에서 쓰지 않는 변수 _","say":["`for _ in range(n_layers)` 의 밑줄은 '번호를 안 쓸 거예요' 라는 표시예요.","그냥 n_layers 번 되풀이하겠다는 뜻이에요."],"example":"print([0 for _ in range(3)])","out":"[0, 0, 0]"}],"pass3":[{"kind":"formula","head":"Pre-LN 블록 두 줄","tex":"x \\leftarrow x + \\mathrm{Attn}(\\mathrm{LN}(x)),\\qquad x \\leftarrow x + \\mathrm{FFN}(\\mathrm{LN}(x))","parts":[{"sym":"\\mathrm{LN}(x)","say":"층 정규화를 먼저 걸어요. 이것이 Pre-LN"},{"sym":"x + \\cdots","say":"잔차 연결. 원래 값을 그대로 더해요"},{"sym":"\\mathrm{Attn}","say":"정보를 옮기는 칸"},{"sym":"\\mathrm{FFN}","say":"정보를 바꾸는 칸"}],"whole":"더하기가 만드는 깨끗한 길이 **항등 경로(Identity Path)** 예요. **기울기(Gradient)** 가 이 길로 곧장 앞층까지 가요."},{"kind":"code","head":"트랜스포머 블록과 미니 트랜스포머","file":"Lab3 노트북 셀 29","code":"class TransformerBlock(nn.Module):\n    def __init__(self, d_model, n_heads):\n        super().__init__()\n        self.ln1  = nn.LayerNorm(d_model)\n        self.attn = MultiHeadSelfAttention(d_model, n_heads, causal=True)\n        self.ln2  = nn.LayerNorm(d_model)\n        self.ffn  = nn.Sequential(\n            nn.Linear(d_model, 4 * d_model), nn.GELU(),\n            nn.Linear(4 * d_model, d_model),\n        )\n\n    def forward(self, x):\n        x = x + self.attn(self.ln1(x))     # residual 1: attention MOVES information\n        x = x + self.ffn(self.ln2(x))      # residual 2: the FFN TRANSFORMS it\n        return x\n\n\nclass MiniTransformer(nn.Module):\n    def __init__(self, vocab, d_model=64, n_heads=1, n_layers=1, max_len=64,\n                 use_pe=True):\n        super().__init__()\n        self.use_pe = use_pe\n        self.emb    = nn.Embedding(vocab, d_model)\n        self.register_buffer(\"pe\", sinusoidal_pe(max_len, d_model))\n        self.blocks = nn.ModuleList([TransformerBlock(d_model, n_heads)\n                                     for _ in range(n_layers)])\n        self.ln_f   = nn.LayerNorm(d_model)\n        self.head   = nn.Linear(d_model, vocab)\n\n    def forward(self, idx):\n        x = self.emb(idx)\n        if self.use_pe:\n            x = x + self.pe[:idx.shape[1]]\n        for b in self.blocks:\n            x = b(x)\n        return self.head(self.ln_f(x))\n\nmodel = MiniTransformer(vocab=11)\nprint(model)\nprint(\"\\nparameters:\", sum(p.numel() for p in model.parameters()))","lines":[{"from":1,"to":3,"say":"**트랜스포머(Transformer)** 블록을 새 부품으로 정의해요. 차원과 **헤드(Head)** 수를 받아요."},{"from":4,"to":4,"say":"어텐션 앞에 걸 **층 정규화(Layer Normalization)** 예요."},{"from":5,"to":5,"say":"**멀티 헤드 어텐션(Multi-Head Attention)** 이에요. causal=True 로 미래를 가려요."},{"from":6,"to":6,"say":"FFN 앞에 걸 두 번째 층 정규화예요."},{"from":7,"to":10,"say":"**위치별 피드포워드 신경망(FFN)** 이에요. 64 → 256 → 64 로 부풀렸다 줄여요. 256 은 4 x 64 예요."},{"from":12,"to":12,"say":"블록의 실제 계산이에요."},{"from":13,"to":13,"say":"첫 번째 **잔차 연결(Residual Connection)**. 주석처럼 어텐션은 정보를 옮겨요."},{"from":14,"to":14,"say":"두 번째 잔차 연결. 주석처럼 FFN 은 정보를 바꿔요."},{"from":15,"to":15,"say":"결과를 돌려줘요. 들어온 **모양(Shape)** 그대로예요."},{"from":18,"to":20,"say":"미니 트랜스포머 모델이에요. 어휘 크기, 차원, 헤드 수, 층 수, 최대 길이, 위치 인코딩 사용 여부를 받아요."},{"from":21,"to":22,"say":"부모 준비를 먼저 하고, 위치 인코딩을 쓸지 저장해요."},{"from":23,"to":23,"say":"**임베딩(Embedding)** 표예요. 토큰 번호를 64칸 벡터로 바꿔요."},{"from":24,"to":24,"say":"**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 표를 학습하지 않는 값으로 붙여 둬요."},{"from":25,"to":26,"say":"블록을 n_layers 개 만들어 줄 세워요. 여기서는 1개예요."},{"from":27,"to":27,"say":"마지막에 한 번 더 걸 층 정규화예요."},{"from":28,"to":28,"say":"64칸을 어휘 크기 11 로 바꾸는 출력층이에요. 다음 토큰 점수를 내요."},{"from":30,"to":31,"say":"모델의 실제 계산이에요. 토큰 번호를 임베딩으로 바꿔요."},{"from":32,"to":33,"say":"위치 인코딩을 쓰기로 했으면 입력 길이만큼 잘라 더해요."},{"from":34,"to":35,"say":"블록을 차례로 통과시켜요."},{"from":36,"to":36,"say":"정규화한 뒤 출력층을 지나 어휘마다 점수를 내놔요."},{"from":38,"to":38,"say":"어휘 11 짜리 모델을 만들어요."},{"from":39,"to":40,"say":"모델 구조와 전체 **파라미터(Parameter)** 개수를 출력해요."}],"link":"강의 N4 p.44 A Minimal Block, p.49 잔차, p.50-51 층 정규화와 Pre-LN"},{"kind":"points","head":"저장된 출력 1: 모델 구조 앞부분","items":["`MiniTransformer(`","`(emb): Embedding(11, 64)`","`(blocks): ModuleList(`","`(0): TransformerBlock(`","`(ln1): LayerNorm((64,), eps=1e-05, elementwise_affine=True)`","`(attn): MultiHeadSelfAttention(`"]},{"kind":"points","head":"저장된 출력 2: 파라미터 개수","items":["`(head): Linear(in_features=64, out_features=11, bias=True)`","`)`","`parameters: 51531`"]},{"kind":"steps","head":"51,531 개를 손으로 세기","steps":["**임베딩(Embedding)**: 11 x 64 = 704","**층 정규화(Layer Normalization)** 는 한 개당 64 + 64 = 128, 세 개라 384","**멀티 헤드 어텐션(Multi-Head Attention)**: 16,640 (앞 쪽에서 센 그 값)","**위치별 피드포워드 신경망(FFN)**: 16,640 + 16,448 = 33,088","출력층: 64 x 11 + 11 = 715","704 + 384 + 16,640 + 33,088 + 715 = 51,531"],"answer":"**파라미터(Parameter)** 의 대부분이 FFN 에 있어요. 강의 N4 p.42 가 말한 그대로예요."},{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 레지듀얼 커넥션은 기울기가 계속 소실되거나 폭발하지 않고","그대로 전달해 주는 하이웨이 역할을 합니다.","**항등 경로(Identity Path)** 가 있어서 기울기 전달이 훨씬 안정적이에요."]}],"pass4":[{"kind":"check","q":"**위치별 피드포워드 신경망(FFN)** 의 중간 차원이 256 인 까닭은?","choices":["강의대로 4 x d 를 쓰기 때문(4 x 64)","**헤드(Head)** 가 4개라서","어휘가 11 이라서","무작위로 정해서"],"a":0,"why":"교수님: FFN 의 중간 차원은 보통 4d 정도로 확장했다 다시 줄여요. 파라미터가 여기 많이 살아요."},{"kind":"english","head":"답안 문장","en":"Pre-LN 트랜스포머 블록은 층 정규화를 먼저 건 뒤 멀티 헤드 셀프 어텐션과 위치별 피드포워드 신경망을 차례로 통과시키고, 각각의 출력을 입력에 더하는 잔차 연결을 둬서 항등 경로로 기울기가 곧장 흐르게 한다.","ko":"어텐션은 옮기고 FFN 은 바꿔요. 잔차 연결이 둘 다에 붙어요.","tip":"'정규화 → 어텐션 → 더하기, 정규화 → FFN → 더하기' 순서로 외워요."},{"kind":"warn","head":"헷갈리는 점","items":["**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 은 **파라미터(Parameter)** 에 안 들어가요. 51,531 에 빠져 있어요.","Pre-LN 은 정규화가 먼저, Post-LN 은 더한 뒤 정규화예요. 2017년 원논문은 Post-LN 이었어요."]}]},{"p":18,"title":"4.3 어텐션이 눈에 보이는 과제: 거꾸로 말하기","terms":["Attention","Head","Next Token Prediction","Token","Causal Masking"],"pass1":[{"kind":"say","lines":["모델이 무작위 숫자 8개를 읽고, 구분자 다음에 그 숫자들을 거꾸로 내놔야 해요.","순수한 정보 옮기기 문제라서 **헤드(Head)** 가 어디를 봤는지 그림으로 볼 수 있어요."]},{"kind":"analogy","head":"거꾸로 말하기 시험","scene":"선생님이 숫자 여덟 개를 불러 주고 '자, 이제 거꾸로' 하면, 여러분은 매번 딱 한 자리를 떠올려요.","map":[["딱 한 자리를 떠올리기","**어텐션(Attention)** 이 한 곳을 보기"],["어디를 떠올렸는지","어텐션 그림"],["한 명이 맡기","**헤드(Head)** 1개만 쓰기"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**reverse the sequence** = 시퀀스를 뒤집어요.","**It is a pure routing problem** = 순수한 정보 배달 문제예요.","**the head has to look at exactly one earlier position** = **헤드(Head)** 가 정확히 앞의 한 자리를 봐야 해요.","**We use one head here on purpose** = 그림이 또렷하도록 일부러 헤드를 하나만 써요."]},{"kind":"compare","head":"과제의 모양","cols":["부분","내용"],"rows":[["앞 절반","무작위 숫자 8개. 절대 못 맞혀요"],["가운데","구분자 기호 하나"],["뒤 절반","앞 8개를 거꾸로. 배울 수 있는 부분"]]},{"kind":"points","head":"예시 그대로 읽기","items":["`3 1 4 1 5 9 2 6 | 6 2 9 5 1 4 1 3`","구분자 뒤 첫 **토큰(Token)** 6 은 구분자 앞 마지막 숫자 6 을 가져온 거예요.","그다음 2 는 그 앞의 2 예요. 자리를 하나씩 거슬러 올라가요."]}],"pass3":[{"kind":"points","head":"왜 이 과제를 고르나","items":["**다음 토큰 예측(Next Token Prediction)** 과제인데 정답이 앞에 그대로 있어요.","그래서 어텐션이 '정확히 그 자리' 를 봤는지 눈으로 확인할 수 있어요.","**인과 마스킹(Causal Masking)** 이 없으면 뒤를 훔쳐볼 수 있는지도 같이 시험해요."]},{"kind":"points","head":"강의와 짝","items":["N4 p.26 Alignment, Learned for Free 가 이 실험의 주제예요.","아무도 '15 번째를 봐' 라고 가르쳐 주지 않았는데 스스로 배워요."]}],"pass4":[{"kind":"check","q":"왜 **헤드(Head)** 를 일부러 1개만 쓰나요?","choices":["어텐션 그림이 또렷해서 해석하기 쉽기 때문","**파라미터(Parameter)** 를 아끼려고","속도 때문","여러 개는 안 되기 때문"],"a":0,"why":"노트북 말: 그림이 명확하도록 일부러 헤드 1개를 써요. 끝나고 n_heads=2 로 다시 돌려 봐도 좋아요."},{"kind":"warn","head":"헷갈리는 점","items":["앞 절반은 무작위라 아무리 똑똑해도 못 맞혀요. 이게 나중에 아주 중요한 단서가 돼요."]}]},{"p":19,"title":"학습 문제지 만들기","terms":["Token","Vocabulary","Tensor","Shape","Next Token Prediction","Embedding"],"pass1":[{"kind":"say","lines":["숫자 8개, 구분자, 거꾸로 8개를 이어 붙여 한 줄짜리 문제를 만들어요.","입력은 마지막 하나를 뺀 것, 정답은 한 칸 민 것이에요.","둘 다 번호가 담긴 **텐서(Tensor)** 예요."]}],"pass2":[{"kind":"points","head":"**어휘(Vocabulary)** 정하기","items":["숫자 **토큰(Token)** 0에서 9 까지 열 개예요.","거기에 구분자 기호 하나를 더해 어휘 크기는 11 이에요.","그래서 **임베딩(Embedding)** 표가 11줄짜리예요."]},{"kind":"pyterm","name":"torch.randint 와 Generator","say":["`torch.randint(10, (bs, 8), generator=gen)` 은 0에서 9 까지 숫자를 그 **모양(Shape)** 대로 뽑아요.","`torch.Generator().manual_seed(100)` 은 따로 쓰는 난수 손잡이예요. 씨앗을 주면 늘 같은 문제가 나와요."],"example":"import torch\ng = torch.Generator().manual_seed(0)\nprint(tuple(torch.randint(10, (2, 3), generator=g).shape))","out":"(2, 3)"},{"kind":"pyterm","name":"torch.cat 과 .flip","say":["`torch.cat([a, b, c], dim=1)` 은 옆으로 이어 붙여요.","`a.flip(1)` 은 1번 축의 순서를 거꾸로 뒤집어요.","`torch.full((bs, 1), SEP)` 은 구분자 번호로만 채운 한 칸이에요."],"example":"import torch\nprint(torch.tensor([[1, 2, 3]]).flip(1))","out":"tensor([[3, 2, 1]])"},{"kind":"pyterm","name":"잘라 내기 [:, :-1] 과 [:, 1:]","say":["`seq[:, :-1]` 은 마지막 칸을 뺀 것, `seq[:, 1:]` 은 첫 칸을 뺀 것이에요.","이 둘이 짝이 되면 '한 칸 뒤' 가 정답이 돼요. **다음 토큰 예측(Next Token Prediction)** 이에요.","`.contiguous()` 는 메모리를 가지런히 정리해 달라는 부탁이에요."],"example":"import torch\nx = torch.tensor([[1, 2, 3]])\nprint(x[:, :-1], x[:, 1:])","out":"tensor([[1, 2]]) tensor([[2, 3]])"},{"kind":"pyterm","name":"join 과 안쪽 for","say":["`\" \".join(...)` 은 조각들을 빈칸으로 이어 한 글자열로 만들어요.","`\"|\" if 조건 else str(int(t))` 는 조건에 따라 둘 중 하나를 고르는 짧은 if 예요."],"example":"print(\" \".join(str(i) for i in (1, 2, 3)))","out":"1 2 3"}],"pass3":[{"kind":"code","head":"문제지와 정답지 만들기","file":"Lab3 노트북 셀 31","code":"N_SYM, K = 10, 8            # digits 0..9, copy length 8\nSEP, VOCAB = N_SYM, N_SYM + 1\nSEQ_LEN = 2 * K             # model input length (the full sequence is 17, shifted by 1)\n\ndef make_batch(bs, gen):\n    a   = torch.randint(N_SYM, (bs, K), generator=gen)\n    seq = torch.cat([a, torch.full((bs, 1), SEP), a.flip(1)], dim=1)   # a | reverse(a)\n    return seq[:, :-1].contiguous(), seq[:, 1:].contiguous()           # inputs, targets\n\ndef show(row):\n    return \" \".join(\"|\" if int(t) == SEP else str(int(t)) for t in row)\n\ng = torch.Generator().manual_seed(100)\nxb, yb = make_batch(2, g)\nprint(\"input  :\", show(xb[0]))\nprint(\"target :\", show(yb[0]), \"  (= input shifted by one)\")","lines":[{"from":1,"to":1,"say":"숫자 종류 10개, 되풀이할 길이 8 로 정해요."},{"from":2,"to":2,"say":"구분자 번호는 10, **어휘(Vocabulary)** 크기는 11 이에요."},{"from":3,"to":3,"say":"모델이 받는 길이는 2 x 8 = 16 이에요. 주석처럼 전체는 17 이고 한 칸 밀려요."},{"from":5,"to":5,"say":"묶음 크기와 난수 손잡이를 받아 문제를 만드는 함수예요."},{"from":6,"to":6,"say":"0에서 9 까지 숫자를 (묶음, 8) **모양(Shape)** 으로 뽑아요."},{"from":7,"to":7,"say":"숫자, 구분자, 거꾸로 숫자를 옆으로 이어 붙여요. 길이 17 이 돼요."},{"from":8,"to":8,"say":"마지막을 뺀 것을 입력, 첫 칸을 뺀 것을 정답으로 돌려줘요."},{"from":10,"to":11,"say":"한 줄을 보기 좋게 글자열로 바꾸는 함수예요. 구분자는 세로줄로 찍어요."},{"from":13,"to":13,"say":"씨앗 100 짜리 난수 손잡이를 만들어요."},{"from":14,"to":14,"say":"문제 2개를 만들어요."},{"from":15,"to":16,"say":"첫 문제의 입력과 정답을 출력해요. 주석처럼 정답은 입력을 한 칸 민 것이에요."}],"link":"강의 N4 p.43 자기회귀 언어 모델의 다음 토큰 예측"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`input  : 0 2 5 9 5 1 2 8 | 8 2 1 5 9 5 2`","`target : 2 5 9 5 1 2 8 | 8 2 1 5 9 5 2 0   (= input shifted by one)`"]},{"kind":"steps","head":"출력 한 줄 읽기","steps":["입력: 0 2 5 9 5 1 2 8 | 8 2 1 5 9 5 2 (16칸)","정답: 2 5 9 5 1 2 8 | 8 2 1 5 9 5 2 0 (16칸)","정답은 입력을 왼쪽으로 한 칸 민 것이에요.","곧 '입력 i 번째를 보고 i+1 번째를 맞혀라' 예요."],"answer":"구분자 뒤부터는 정답이 앞에 그대로 있어요. 어디를 볼지만 알면 돼요."}],"pass4":[{"kind":"check","q":"전체 길이는 17 인데 입력과 정답이 16 인 까닭은?","choices":["한 칸 밀어 짝을 만들려고 앞뒤를 하나씩 잘라서","**어휘(Vocabulary)** 가 11 이라서","**토큰(Token)** 이 모자라서","묶음이 2개라서"],"a":0,"why":"입력은 마지막 칸을, 정답은 첫 칸을 잘랐어요. 둘 다 16칸이 되고 한 칸씩 어긋나요."},{"kind":"warn","head":"헷갈리는 점","items":["구분자도 하나의 **토큰(Token)** 이에요. 그래서 **어휘(Vocabulary)** 가 10 이 아니라 11 이에요.","여기 숫자는 씨앗 100 으로 뽑은 것이라, 씨앗을 바꾸면 다른 숫자가 나와요."]}]},{"p":20,"title":"학습 함수: 400걸음이면 끝나요","terms":["Optimizer","Cross-Entropy","Loss Function","Gradient","Causal Masking","Positional Encoding","Tensor","Softmax"],"pass1":[{"kind":"say","lines":["모델을 만들고, 문제를 뽑고, 틀린 만큼 고치기를 400번 되풀이해요.","고치는 일은 **옵티마이저(Optimizer)** 가 맡아요.","그다음 학습에 안 쓴 문제 512개로 채점해요. 전부 2초 안팎이에요."]}],"pass2":[{"kind":"points","head":"이 함수가 재는 두 가지","items":["거꾸로 말하기 정확도: 구분자 뒤 절반만 채점해요. 배울 수 있는 부분이에요.","앞 절반의 **손실 함수(Loss Function)** 값: 무작위라서 찍기 수준인 2.303 이 나와야 정상이에요.","두 숫자를 나란히 봐야 뒤에서 마스크 실험을 읽을 수 있어요."]},{"kind":"pyterm","name":"기본값이 있는 함수","say":["`def train(use_pe=True, causal=True, n_heads=1, steps=400, ...)` 처럼 기본값을 적어 둬요.","`train()` 이라고만 부르면 전부 기본값을 써요.","`train(use_pe=False)` 처럼 하나만 바꿔 부를 수도 있어요."],"example":"def f(a=1, b=2):\n    return a + b\nprint(f(), f(b=10))","out":"3 11"},{"kind":"pyterm","name":"옵티마이저 세 줄","say":["`opt.zero_grad()` 는 지난 **기울기(Gradient)** 를 0 으로 지워요.","`loss.backward()` 는 기울기를 새로 구해요.","`opt.step()` 은 그 기울기를 보고 **파라미터(Parameter)** 를 한 걸음 고쳐요. 이 셋이 한 묶음이에요."],"example":"import torch\nx = torch.tensor([1.0], requires_grad=True)\n(x * x).sum().backward()\nprint(x.grad)","out":"tensor([2.])"},{"kind":"pyterm","name":"F.cross_entropy 와 reshape(-1, V)","say":["`F.cross_entropy(점수, 정답)` 은 **소프트맥스(Softmax)** 와 -log 를 함께 계산한 **교차 엔트로피(Cross-Entropy)** 예요.","`.reshape(-1, VOCAB)` 은 모든 자리를 한 줄로 펴요. -1 은 '알아서 계산해 줘' 라는 뜻이에요."],"example":"print((-1, 11))","out":"(-1, 11)"},{"kind":"pyterm","name":"m.eval() 과 torch.no_grad()","say":["`m.eval()` 은 '이제 학습 말고 채점 모드' 라는 표시예요.","`with torch.no_grad():` 안에서는 **기울기(Gradient)** 를 기록하지 않아 빠르고 가벼워요."],"example":"import torch\nwith torch.no_grad():\n    print(torch.zeros(2).sum().requires_grad)","out":"False"},{"kind":"pyterm","name":"argmax 와 .float().mean()","say":["`logits.argmax(-1)` 은 점수가 가장 높은 후보의 번호를 골라요.","`(예측 == 정답).float().mean()` 은 맞은 비율, 곧 정확도예요. 참은 1, 거짓은 0 으로 세요."],"example":"import torch\nprint((torch.tensor([1, 2]) == torch.tensor([1, 3])).float().mean().item())","out":"0.5"}],"pass3":[{"kind":"code","head":"학습과 채점을 한 함수로","file":"Lab3 노트북 셀 32","code":"def train(use_pe=True, causal=True, n_heads=1, steps=400, seed=0, verbose=True):\n    torch.manual_seed(seed)\n    gen = torch.Generator().manual_seed(seed + 100)\n    m   = MiniTransformer(VOCAB, d_model=64, n_heads=n_heads,\n                          max_len=SEQ_LEN, use_pe=use_pe)\n    for blk in m.blocks:                       # switch the mask off for the ablation\n        blk.attn.causal = causal\n    opt = torch.optim.AdamW(m.parameters(), lr=3e-3)\n\n    t0 = time.time()\n    for step in range(steps):\n        x, y = make_batch(64, gen)\n        loss = F.cross_entropy(m(x).reshape(-1, VOCAB), y.reshape(-1))\n        opt.zero_grad(); loss.backward(); opt.step()\n    secs = time.time() - t0\n\n    m.eval()\n    gt = torch.Generator().manual_seed(999)\n    x, y = make_batch(512, gt)\n    with torch.no_grad():\n        logits = m(x)\n    # accuracy on the reversed half only\n    acc = (logits.argmax(-1)[:, K:] == y[:, K:]).float().mean().item()\n    # loss on the FIRST half, which is genuinely random -> chance is ln(10) = 2.303\n    first = F.cross_entropy(logits[:, :K - 1].reshape(-1, VOCAB),\n                            y[:, :K - 1].reshape(-1)).item()\n    if verbose:\n        print(f\"trained in {secs:.1f}s | reverse accuracy = {acc:.3f} | \"\n              f\"loss on the random first half = {first:.3f}\")\n    return m, acc, first\n\nmodel, acc, first = train()","lines":[{"from":1,"to":1,"say":"**위치 인코딩(Positional Encoding)** 사용 여부, 마스크 여부, **헤드(Head)** 수 등을 받아요."},{"from":2,"to":3,"say":"씨앗을 고정해요. 그래야 같은 조건이면 같은 결과가 나와요."},{"from":4,"to":5,"say":"미니 **트랜스포머(Transformer)** 모델을 만들어요. 차원 64, 최대 길이 16 이에요."},{"from":6,"to":7,"say":"실험을 위해 블록마다 **인과 마스킹(Causal Masking)** 을 켜거나 꺼요."},{"from":8,"to":8,"say":"**옵티마이저(Optimizer)** AdamW 를 붙여요. 학습률은 0.003 이에요."},{"from":10,"to":10,"say":"시간을 재기 시작해요."},{"from":11,"to":11,"say":"400걸음을 되풀이해요."},{"from":12,"to":12,"say":"매 걸음 새 문제 64개를 뽑아요."},{"from":13,"to":13,"say":"모델 점수와 정답으로 **교차 엔트로피(Cross-Entropy)** 를 구해요. 이것이 **손실 함수(Loss Function)** 예요."},{"from":14,"to":14,"say":"기울기 지우기, 기울기 구하기, 한 걸음 걷기를 한 줄에 몰아 썼어요."},{"from":15,"to":15,"say":"걸린 시간을 계산해요."},{"from":17,"to":17,"say":"채점 모드로 바꿔요."},{"from":18,"to":18,"say":"채점용 난수 손잡이는 씨앗 999 로 따로 둬요. 학습에 쓴 문제와 겹치지 않게요."},{"from":19,"to":19,"say":"채점용 문제 512개를 뽑아요."},{"from":20,"to":21,"say":"**기울기(Gradient)** 없이 모델 점수를 구해요."},{"from":22,"to":23,"say":"구분자 뒤 절반만 채점해 거꾸로 말하기 정확도를 내요."},{"from":24,"to":26,"say":"주석처럼 앞 절반은 진짜 무작위예요. 찍기 수준은 ln(10) = 2.303 이에요."},{"from":27,"to":29,"say":"학습 시간, 정확도, 앞 절반 손실을 한 줄로 출력해요."},{"from":30,"to":30,"say":"모델과 두 숫자를 돌려줘요."},{"from":32,"to":32,"say":"기본 설정으로 한 번 학습시켜요."}],"link":"강의 N4 p.43 인과 마스킹, p.40 위치 인코딩"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`trained in 23.9s | reverse accuracy = 1.000 | loss on the random first half = 2.311`"]},{"kind":"steps","head":"2.303 이 어디서 나오나","steps":["앞 절반은 0에서 9 까지 무작위 숫자예요.","아무 단서가 없으면 열 개 후보에 확률 1/10 씩 줄 수밖에 없어요.","**교차 엔트로피(Cross-Entropy)** 는 -log(1/10) = ln(10) = 2.303","저장된 출력의 2.311 은 이 값에 거의 붙어 있어요."],"answer":"정직한 모델은 앞 절반에서 2.303 보다 잘할 수 없어요. 이게 뒤 실험의 열쇠예요."}],"pass4":[{"kind":"check","q":"`opt.zero_grad(); loss.backward(); opt.step()` 의 순서가 중요한 까닭은?","choices":["지난 **기울기(Gradient)** 를 지우고, 새로 구하고, 그다음 걸어야 하기 때문","속도 때문","**소프트맥스(Softmax)** 때문","순서는 상관없어요"],"a":0,"why":"지우지 않으면 기울기가 계속 쌓여요. 3주차 실습에서도 같은 세 줄을 썼어요."},{"kind":"warn","head":"헷갈리는 점","items":["학습 시간 23.9초는 컴퓨터마다 달라요. 실행할 때마다 달라지는 숫자예요.","**옵티마이저(Optimizer)** 를 AdamW 에서 다른 것으로 바꾸면 결과가 달라져요.","정확도 1.000 은 구분자 뒤 절반만 잰 값이에요. 문장 전체가 아니에요.","씨앗을 고정했어도 PyTorch 버전이 다르면 소수 아래가 조금 달라질 수 있어요."]}]},{"p":21,"title":"정말 과제를 푸나: 한 줄 찍어 보기","terms":["Next Token Prediction","Causal Masking","Attention","Autoregressive","Token"],"pass1":[{"kind":"say","lines":["학습한 모델에 문제 하나를 넣고, 입력과 정답과 예측을 나란히 찍어 봐요.","앞 절반은 엉망이고 뒤 절반은 완벽해야 정상이에요."]}],"pass2":[{"kind":"pyterm","name":"argmax(-1) 로 예측 꺼내기","say":["모델은 자리마다 **어휘(Vocabulary)** 크기 11 짜리 점수를 내놔요.","`.argmax(-1)` 은 그중 가장 높은 번호를 골라요. 그것이 모델의 답이에요."],"example":"import torch\nprint(torch.tensor([[0.1, 0.9, 0.2]]).argmax(-1))","out":"tensor([1])"},{"kind":"pyterm","name":"주석 # 은 설명","say":["`# does it actually do the task?` 처럼 우물 정자로 시작하면 실행되지 않는 설명이에요.","노트북이 여러분에게 말을 거는 방식이에요."],"example":"# 이 줄은 실행되지 않아요\nprint(1)","out":"1"}],"pass3":[{"kind":"code","head":"한 문제를 넣고 예측 보기","file":"Lab3 노트북 셀 33","code":"# does it actually do the task?\nmodel.eval()\ngt = torch.Generator().manual_seed(7)\nx, y = make_batch(1, gt)\nwith torch.no_grad():\n    pred = model(x).argmax(-1)\n\nprint(\"input     :\", show(x[0]))\nprint(\"target    :\", show(y[0]))\nprint(\"predicted :\", show(pred[0]))\nprint(\"\\n(only the part after '|' is learnable - the first half is random noise)\")","lines":[{"from":1,"to":2,"say":"설명 주석이고, 모델을 채점 모드로 바꿔요."},{"from":3,"to":3,"say":"씨앗 7 짜리 난수 손잡이를 만들어요."},{"from":4,"to":4,"say":"문제 1개를 뽑아요."},{"from":5,"to":6,"say":"**기울기(Gradient)** 없이 모델을 돌리고, 자리마다 가장 높은 번호를 골라요."},{"from":8,"to":10,"say":"입력, 정답, 예측 세 줄을 나란히 출력해요."},{"from":11,"to":11,"say":"구분자 뒤만 배울 수 있고 앞 절반은 무작위 잡음이라고 알려 줘요."}],"link":"강의 N4 p.43 미래를 가린 자기회귀 예측"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`input     : 5 2 1 6 3 7 7 9 | 9 7 7 3 6 1 2`","`target    : 2 1 6 3 7 7 9 | 9 7 7 3 6 1 2 5`","`predicted : 8 8 8 8 8 7 7 | 9 7 7 3 6 1 2 5`","`(only the part after '|' is learnable - the first half is random noise)`"]},{"kind":"points","head":"출력 읽기","items":["입력: `5 2 1 6 3 7 7 9 | 9 7 7 3 6 1 2`","예측: `8 8 8 8 8 7 7 | 9 7 7 3 6 1 2 5`","앞 절반은 8 만 늘어놓아요. 못 맞히니까 아무거나 찍는 거예요.","구분자 뒤는 정답과 한 글자도 안 틀려요. **어텐션(Attention)** 이 제자리를 찾은 거예요."]}],"pass4":[{"kind":"check","q":"앞 절반 예측이 `8 8 8 8 8 ...` 인 것이 왜 정상인가요?","choices":["무작위 숫자라 단서가 없어 아무 값이나 내놓기 때문","모델이 고장 나서","**인과 마스킹(Causal Masking)** 이 잘못돼서","학습이 모자라서"],"a":0,"why":"**자기회귀(Autoregressive)** 모델은 미래를 못 봐요. 앞 절반은 원래 맞힐 수 없어요."},{"kind":"warn","head":"헷갈리는 점","items":["뒤 절반이 완벽한 것은 정답이 앞에 이미 있기 때문이에요. 모델이 '기억' 해서가 아니라 '보고' 가져온 거예요.","만약 앞 절반까지 맞힌다면 그건 잘한 게 아니라 미래를 훔쳐봤다는 뜻이에요."]}]},{"p":22,"title":"4.4 헤드가 무엇을 배웠나: 어텐션 그림 읽기","terms":["Attention Weight","Head","Interpretability","Query","Key","Alignment"],"pass1":[{"kind":"say","lines":["모델이 **어텐션(Attention)** 으로 과제를 풀었다면, 그림에 깔끔한 반대각선이 보여야 해요.","자리 i 의 **쿼리(Query)** 가 자리 15-i 의 **키(Key)** 를 보는 모양이에요."]},{"kind":"analogy","head":"어텐션 그림 읽는 법","scene":"좌석 배치도 같아요. 가로줄은 '지금 말하는 사람', 세로줄은 '쳐다보는 사람' 이고, 색이 진할수록 오래 쳐다본 거예요.","map":[["세로축(행)","**쿼리(Query)**, 지금 정하는 자리"],["가로축(열)","**키(Key)**, 보고 있는 자리"],["진한 칸","큰 **어텐션 가중치(Attention Weight)**"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**Look at the attention map** = 어텐션 지도를 보세요.","**a clean anti-diagonal** = 깔끔한 반대각선.","**query at position i looking at key at position 15-i** = 자리 i 의 쿼리가 자리 15-i 의 키를 봐요.","**the head's top choice is the correct position** = **헤드(Head)** 의 1순위가 정답 자리예요."]},{"kind":"pyterm","name":"last_attn 꺼내 오기","say":["`model.blocks[0].attn.last_attn[0, 0]` 은 0번 블록, 0번 묶음, 0번 **헤드(Head)** 의 어텐션이에요.","앞에서 모듈이 계산할 때마다 저장해 둔 값이에요. 그래서 나중에 볼 수 있어요."],"example":"import torch\nprint(tuple(torch.zeros(2, 4, 7, 7)[0, 0].shape))","out":"(7, 7)"},{"kind":"pyterm","name":"눈금에 이름 붙이기","say":["`ax.set_xticks(range(16))` 은 눈금 자리를, `set_xticklabels(labels)` 는 그 이름을 정해요.","여기서는 `0:5`, `8:|` 처럼 자리 번호와 기호를 함께 적어요."],"example":"labels = [f\"{i}:{s}\" for i, s in enumerate('ab')]\nprint(labels)","out":"['0:a', '1:b']"},{"kind":"pyterm","name":"A_all[:, queries, correct]","say":["여러 축에 목록을 한꺼번에 넣어 원하는 칸들만 뽑는 방법이에요.","'각 쿼리 자리에서 정답 키 자리에 준 **어텐션 가중치(Attention Weight)**' 만 모아 와요."],"example":"print([15 - i for i in range(8, 15)])","out":"[7, 6, 5, 4, 3, 2, 1]"}],"pass3":[{"kind":"code","head":"어텐션 지도 그리고 숫자로도 재기","file":"Lab3 노트북 셀 35","code":"A = model.blocks[0].attn.last_attn[0, 0]        # (T, T): batch 0, head 0\nlabels = [f\"{i}:{'|' if int(t) == SEP else int(t)}\" for i, t in enumerate(x[0])]\n\nfig, ax = plt.subplots(figsize=(6.6, 5.8))\nim = ax.imshow(A, cmap=\"Blues\", vmin=0, vmax=A.max())\nax.set_xticks(range(SEQ_LEN)); ax.set_xticklabels(labels, rotation=90, fontsize=8)\nax.set_yticks(range(SEQ_LEN)); ax.set_yticklabels(labels, fontsize=8)\nax.set_xlabel(\"key  (what it looks AT)   -  labelled position:symbol\")\nax.set_ylabel(\"query  (the position deciding)\")\nax.set_title(\"our trained head: the anti-diagonal is the reversal\")\nfig.colorbar(im, ax=ax, fraction=0.046)\nplt.tight_layout(); plt.show()\n\n# and the same thing as a number, averaged over 256 sequences\ngt = torch.Generator().manual_seed(555)\nxb, _ = make_batch(256, gt)\nwith torch.no_grad():\n    model(xb)\nA_all = model.blocks[0].attn.last_attn[:, 0]\nqueries = list(range(K, SEQ_LEN - 1))\ncorrect = [SEQ_LEN - 1 - i for i in queries]\nhit  = (A_all[:, queries].argmax(-1) == torch.tensor(correct)).float().mean()\nmass = A_all[:, queries, correct].mean()\nprint(f\"the head's top choice is the correct position {hit*100:.1f}% of the time\")\nprint(f\"and it puts {mass*100:.0f}% of its attention mass exactly there\")","lines":[{"from":1,"to":1,"say":"0번 블록 0번 **헤드(Head)** 의 어텐션 행렬을 꺼내요. 주석처럼 (T, T) 예요."},{"from":2,"to":2,"say":"눈금 이름을 만들어요. 자리 번호와 그 자리의 기호를 붙여 써요."},{"from":4,"to":4,"say":"그림 칸을 하나 만들어요."},{"from":5,"to":5,"say":"어텐션 행렬을 파란 히트맵으로 칠해요. 진할수록 큰 값이에요."},{"from":6,"to":7,"say":"가로축과 세로축 눈금에 이름을 붙여요."},{"from":8,"to":9,"say":"가로축은 **키(Key)**, 세로축은 **쿼리(Query)** 라고 적어요."},{"from":10,"to":10,"say":"제목을 붙여요. 반대각선이 곧 뒤집기라는 뜻이에요."},{"from":11,"to":11,"say":"색 막대를 붙여요."},{"from":12,"to":12,"say":"여백을 정리하고 화면에 띄워요."},{"from":14,"to":16,"say":"이번에는 눈이 아니라 숫자로 재요. 문제 256개를 새로 뽑아요."},{"from":17,"to":18,"say":"**기울기(Gradient)** 없이 한 번 돌려 어텐션을 저장시켜요."},{"from":19,"to":19,"say":"묶음 전체의 0번 헤드 어텐션을 가져와요."},{"from":20,"to":21,"say":"채점할 쿼리 자리와, 각 자리의 정답 키 자리(15 빼기 i)를 만들어요."},{"from":22,"to":22,"say":"헤드의 1순위가 정답 자리와 같은 비율을 재요."},{"from":23,"to":23,"say":"정답 자리에 실제로 몰린 **어텐션 가중치(Attention Weight)** 의 평균을 재요."},{"from":24,"to":25,"say":"두 숫자를 백분율로 출력해요."}],"link":"강의 N4 p.26 Alignment, Learned for Free, p.25 Interpretability"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`<Figure size 660x580 with 2 Axes>`","`[그림 출력]`","`the head's top choice is the correct position 99.8% of the time`","`and it puts 64% of its attention mass exactly there`"]},{"kind":"steps","head":"반대각선이 무슨 뜻인가","steps":["길이가 16 이니 자리 번호는 0 부터 15 예요.","자리 8 은 자리 7 을, 자리 9 는 자리 6 을 봐야 해요.","두 번호를 더하면 언제나 15 예요. 그래서 15 빼기 i 예요.","그림에서는 왼쪽 아래로 내려가는 대각선 반대 방향 줄이 돼요."],"answer":"1순위가 맞은 비율 99.8%, 정답 자리에 몰린 가중치 64%. 아무도 가르쳐 주지 않은 **정렬(Alignment)** 이에요."}],"pass4":[{"kind":"check","q":"어텐션 그림에서 진한 칸이 뜻하는 것은?","choices":["그 **쿼리(Query)** 자리가 그 **키(Key)** 자리를 많이 봤다는 뜻","그 자리의 값이 크다는 뜻","그 자리가 정답이라는 뜻","**파라미터(Parameter)** 가 크다는 뜻"],"a":0,"why":"히트맵의 값은 **어텐션 가중치(Attention Weight)** 예요. 행마다 더하면 1 이에요."},{"kind":"warn","head":"헷갈리는 점","items":["1순위 정답률 99.8% 와 몰린 가중치 64% 는 다른 숫자예요. 1순위는 맞지만 나머지 36% 는 다른 데로 흩어져요.","**해석 가능성(Interpretability)** 은 '어디서 가져왔나' 까지예요. '왜 그렇게 답했나' 는 아니에요."]}]},{"p":23,"title":"4.5 장벽 세 개를 실험으로 확인하기","terms":["Positional Encoding","Causal Masking","Permutation Equivariance","Cross-Entropy","Loss Function"],"pass1":[{"kind":"say","lines":["강의는 **위치 인코딩(Positional Encoding)** 과 **인과 마스킹(Causal Masking)** 이 선택이 아니라고 했어요.","하나씩 빼 보고 무슨 일이 생기는지 재요. 한 번에 2초쯤 걸려요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**The three barriers, now as an experiment** = 장벽 세 개를 이제 실험으로.","**positional encoding and the causal mask are not optional** = 위치 인코딩과 인과 마스크는 선택 사항이 아니에요.","**Let us remove them one at a time and measure** = 하나씩 빼 보고 측정해 봅시다."]},{"kind":"pyterm","name":"안 쓸 값은 밑줄로","say":["`_, acc_base, first_base = train()` 은 세 값 중 첫 번째(모델)는 버리고 둘만 받아요.","같은 함수를 조건만 바꿔 세 번 불러요."],"example":"_, a, b = (0, 1, 2)\nprint(a, b)","out":"1 2"},{"kind":"pyterm","name":"글자열 곱하기와 칸 맞추기","say":["`\"=\" * 68` 은 등호를 68번 이어 붙여 줄을 그어요.","`f\"{'setting':<34}\"` 는 왼쪽 정렬 34칸, `{acc:>13.3f}` 는 오른쪽 정렬 13칸에 소수 셋째 자리예요.","표를 손으로 그리는 방법이에요."],"example":"print(\"=\" * 10)","out":"=========="},{"kind":"pyterm","name":"math.log","say":["`math.log(10)` 은 자연로그 ln(10) 이에요. 값은 약 2.303 이에요.","후보가 10개일 때 아무것도 모르는 모델의 **교차 엔트로피(Cross-Entropy)** 예요."],"example":"import math\nprint(round(math.log(10), 3))","out":"2.303"}],"pass3":[{"kind":"code","head":"기본, 위치 인코딩 빼기, 마스크 빼기","file":"Lab3 노트북 셀 37","code":"print(\"baseline (positional encoding + causal mask)\")\n_, acc_base, first_base = train()\n\nprint(\"\\nBARRIER 1 -- no positional encoding:\")\n_, acc_nope, first_nope = train(use_pe=False)\n\nprint(\"\\nBARRIER 3 -- no causal mask:\")\n_, acc_nomask, first_nomask = train(causal=False)\n\nprint(\"\\n\" + \"=\" * 68)\nprint(f\"{'setting':<34}{'reverse acc':>13}{'first-half loss':>19}\")\nprint(\"-\" * 68)\nprint(f\"{'baseline':<34}{acc_base:>13.3f}{first_base:>19.3f}\")\nprint(f\"{'no positional encoding':<34}{acc_nope:>13.3f}{first_nope:>19.3f}\")\nprint(f\"{'no causal mask':<34}{acc_nomask:>13.3f}{first_nomask:>19.3f}\")\nprint(\"=\" * 68)\nprint(f\"chance level for the first half = ln(10) = {math.log(10):.3f}\")","lines":[{"from":1,"to":2,"say":"기본 설정으로 학습시켜요. 위치 인코딩과 마스크 둘 다 켠 상태예요."},{"from":4,"to":5,"say":"장벽 1 실험이에요. **위치 인코딩(Positional Encoding)** 만 빼요."},{"from":7,"to":8,"say":"장벽 3 실험이에요. **인과 마스킹(Causal Masking)** 만 빼요."},{"from":10,"to":10,"say":"구분선을 그어요."},{"from":11,"to":12,"say":"표의 머리글이에요. 설정, 거꾸로 정확도, 앞 절반 **손실 함수(Loss Function)** 값 세 칸이에요."},{"from":13,"to":15,"say":"세 실험의 결과를 한 줄씩 찍어요."},{"from":16,"to":16,"say":"아래쪽 구분선을 그어요."},{"from":17,"to":17,"say":"앞 절반의 찍기 수준 ln(10) = 2.303 을 함께 출력해요."}],"link":"강의 N4 p.39-43 세 가지 장벽과 처방"},{"kind":"points","head":"저장된 출력 1: 세 번의 학습","items":["`baseline (positional encoding + causal mask)`","`trained in 23.1s | reverse accuracy = 1.000 | loss on the random first half = 2.311`","`BARRIER 1 -- no positional encoding:`","`trained in 8.3s | reverse accuracy = 0.298 | loss on the random first half = 2.446`","`BARRIER 3 -- no causal mask:`","`trained in 7.7s | reverse accuracy = 1.000 | loss on the random first half = 0.000`"]},{"kind":"points","head":"저장된 출력 2: 정리한 표","items":["`====================================================================`","`setting                             reverse acc    first-half loss`","`--------------------------------------------------------------------`","`baseline                                  1.000              2.311`","`no positional encoding                    0.298              2.446`","`no causal mask                            1.000              0.000`","`====================================================================`"]},{"kind":"steps","head":"표를 숫자로 읽기","steps":["기본: 정확도 1.000, 앞 절반 손실 2.311 (찍기 수준과 거의 같음, 정상)","위치 인코딩 빼기: 정확도 0.298 로 무너짐. 손실 2.446 (여전히 찍기 수준)","마스크 빼기: 정확도 1.000 인데 손실이 0.000","정직한 모델의 한계는 2.303 인데 0.000 은 불가능한 값이에요."],"answer":"**순열 등변성(Permutation Equivariance)** 때문에 위치 인코딩이 없으면 순서를 못 배워요. 마스크가 없으면 미래를 읽어요."}],"pass4":[{"kind":"check","q":"마스크를 뺐더니 앞 절반 **손실 함수(Loss Function)** 값이 0.000 이 된 것은 무슨 뜻인가요?","choices":["미래를 훔쳐봐서 무작위 숫자까지 맞혔다는 뜻","모델이 아주 똑똑해졌다는 뜻","학습이 실패했다는 뜻","**교차 엔트로피(Cross-Entropy)** 가 고장 났다는 뜻"],"a":0,"why":"무작위 숫자를 완벽히 맞히는 것은 불가능해요. 뒤에 있는 정답을 보고 있는 거예요."},{"kind":"warn","head":"헷갈리는 점","items":["마스크를 빼도 정확도는 1.000 이라 언뜻 멀쩡해 보여요. 옆 칸을 꼭 같이 봐야 해요.","학습 시간(23.1초, 8.3초)은 컴퓨터마다 달라요. 실행할 때마다 달라지는 숫자예요.","정확도 0.298 도 씨앗과 버전에 따라 조금 달라질 수 있어요. 무너진다는 사실이 핵심이에요."]}]},{"p":24,"title":"표를 제대로 읽기: 두 숫자가 모두 말을 해요","terms":["Positional Encoding","Causal Masking","Position-wise Feed-Forward Network (FFN)","Attention","Autoregressive","Language Model (LM)","Value"],"pass1":[{"kind":"say","lines":["정확도만 보면 절반만 읽은 거예요. 옆 칸의 손실 값도 함께 읽어야 해요.","장벽 2 는 이 과제에서 안 드러나요. 그것도 중요한 이야기예요."]}],"pass2":[{"kind":"compare","head":"장벽 세 개, 증상과 처방","cols":["장벽","빼면 생기는 일","처방"],"rows":[["1. 순서를 모름","정확도 1.00 → 0.28 로 무너짐","**위치 인코딩(Positional Encoding)**"],["2. 평균만 냄","이 과제에서는 안 드러남","**위치별 피드포워드 신경망(FFN)**"],["3. 미래를 봄","앞 절반 손실이 0.00 (불가능한 값)","**인과 마스킹(Causal Masking)**"]]},{"kind":"points","head":"영어 문장의 뜻","items":["**Read the table carefully, both numbers say something** = 두 숫자 모두 무언가를 말해요.","**Accuracy collapses from ~1.00 to ~0.28** = 정확도가 1.00 에서 0.28 로 무너져요.","**It is reading them from the future** = 미래에서 읽어 오고 있는 거예요.","**reversing a sequence is pure routing** = 뒤집기는 순수한 정보 배달이에요.","**Attention communicates; the FFN computes** = **어텐션(Attention)** 은 통신하고 FFN 은 계산해요."]},{"kind":"points","head":"장벽 2 가 안 드러난 까닭","items":["블록에서 **위치별 피드포워드 신경망(FFN)** 을 빼도 이 과제는 여전히 1.00 이 나와요.","뒤집기는 **밸류(Value)** 를 그대로 옮기기만 하면 되는 일이거든요.","FFN 은 **토큰(Token)** 을 옮기는 게 아니라 바꿔야 하는 과제에서 값을 해요."]}],"pass3":[{"kind":"prof","when":"4주차 2교시 수업","lines":["교수님: 셀프 어텐션에는 배리어가 3개 있어요. 이 배리어 3개를 기억해 봅시다.","순서 정보가 없어서 포지셔널 인코딩이 필요하고,","토큰별 비선형 변환이 필요해서 FFN 이 필요하고,","미래 정보를 차단해야 해서 컨설 마스킹이 필요합니다."]},{"kind":"points","head":"강의와 짝","items":["N4 p.39 Three Things Are Still Missing 이 이 표 전체예요.","N4 p.58 Check Yourself 5번이 '장벽 세 개와 각각의 처방을 말하라' 예요.","시험 1순위 문항이에요."]}],"pass4":[{"kind":"check","q":"**인과 마스킹(Causal Masking)** 없이 학습한 **언어 모델(Language Model)** 이 쓸모없는 까닭은?","choices":["정답을 미리 보고 맞히는 것이라 과제가 시시해지고 아무것도 못 배우기 때문","느려지기 때문","**파라미터(Parameter)** 가 늘기 때문","**어휘(Vocabulary)** 가 커지기 때문"],"a":0,"why":"강의 N4 p.43 그대로예요. **자기회귀(Autoregressive)** 모델은 미래를 가려야 배울 게 생겨요."},{"kind":"english","head":"답안 문장","en":"평범한 셀프 어텐션의 세 가지 장벽은 순서를 모른다는 것, 밸류들의 가중 평균만 낼 수 있다는 것, 미래 토큰을 본다는 것이고, 트랜스포머는 각각 위치 인코딩, 위치별 피드포워드 신경망, 인과 마스킹으로 해결한다.","ko":"장벽 → 처방을 한 쌍씩 묶어서 외워요. 실습에서 1번과 3번은 숫자로 확인했어요.","tip":"'순서, 평균, 미래' 세 글자로 먼저 떠올려요."},{"kind":"warn","head":"시험에서 헷갈리는 점","items":["마스크를 빼면 정확도가 떨어질 거라고 생각하기 쉬운데, 오히려 그대로예요. 손실 쪽이 망가져요.","장벽 2 가 안 드러난 것은 FFN 이 필요 없다는 뜻이 아니라, 이 과제가 배달만 하면 되는 과제라서예요."]}]},{"p":25,"title":"Part 5 진짜 모델의 헤드 들여다보기","terms":["BERT","Head","Attention Weight","Tokenizer","Token","Shape","Parameter"],"pass1":[{"kind":"say","lines":["우리 **헤드(Head)** 는 일이 하나뿐이라 규칙 하나를 깔끔하게 배웠어요.","위키피디아 전체로 학습한 모델의 헤드는 어떻게 생겼을까요?","**버트(BERT)** 를 가볍게 줄인 DistilBERT 를 불러와 어텐션을 직접 꺼내 봐요."]}],"pass2":[{"kind":"points","head":"DistilBERT 가 어떤 모델인가","items":["6층 x 12**헤드(Head)** = 72개 헤드를 갖고 있어요.","**파라미터(Parameter)** 는 6,600만 개예요. 우리 모델의 천 배가 넘어요.","처음 실행할 때 250MB 정도를 내려받아요."]},{"kind":"pyterm","name":"from ... import ...","say":["`from transformers import AutoTokenizer, AutoModel` 은 그 묶음에서 필요한 것만 가져와요.","`import ... as ...` 와 달리 이름을 바로 쓸 수 있어요."],"example":"from math import sqrt\nprint(sqrt(16))","out":"4.0"},{"kind":"pyterm","name":"try / except","say":["`try:` 안을 먼저 해 보고, 오류가 나면 `except:` 아래로 넘어가요.","여기서는 옛 버전에서 안 되는 옵션을 안전하게 건너뛰려고 써요."],"example":"try:\n    int(\"x\")\nexcept ValueError:\n    print(\"안 되네요\")","out":"안 되네요"},{"kind":"pyterm","name":"별표 두 개 **enc","say":["`bert(**enc, output_attentions=True)` 의 별표 둘은 사전을 풀어서 이름표 붙은 값으로 넘겨요.","`output_attentions=True` 는 **어텐션 가중치(Attention Weight)** 도 같이 돌려 달라는 부탁이에요."],"example":"def f(a, b):\n    return a + b\nprint(f(**{\"a\": 1, \"b\": 2}))","out":"3"},{"kind":"pyterm","name":"torch.stack 과 [:, 0]","say":["`torch.stack(out.attentions)` 은 층마다 따로 온 어텐션을 한 덩어리로 쌓아요.","`[:, 0]` 은 묶음의 0번 문장만 골라요. 결과 **모양(Shape)** 은 (층, 헤드, 쿼리, 키) 예요."],"example":"import torch\nprint(tuple(torch.stack([torch.zeros(1, 2, 3, 3)] * 6)[:, 0].shape))","out":"(6, 2, 3, 3)"}],"pass3":[{"kind":"code","head":"DistilBERT 불러오고 어텐션 꺼내기","file":"Lab3 노트북 셀 40","code":"from transformers import AutoTokenizer, AutoModel, logging as hf_logging\nhf_logging.set_verbosity_error()          # keep the output tidy\n\nNAME = \"distilbert-base-uncased\"          # first run downloads ~250 MB\ntok = AutoTokenizer.from_pretrained(NAME)\ntry:\n    bert = AutoModel.from_pretrained(NAME, attn_implementation=\"eager\")\nexcept TypeError:                       # older versions of transformers\n    bert = AutoModel.from_pretrained(NAME)\nbert.eval()\n\nSENT = \"The chef who ran to the store was tired.\"     # the sentence from the lecture\n\ndef attention_for(sentence):\n    enc = tok(sentence, return_tensors=\"pt\")\n    with torch.no_grad():\n        out = bert(**enc, output_attentions=True)\n    A = torch.stack(out.attentions)[:, 0]             # (layers, heads, T, T)\n    return A, tok.convert_ids_to_tokens(enc[\"input_ids\"][0])\n\nA, tokens = attention_for(SENT)\nprint(\"tokens    :\", tokens)\nprint(\"attention :\", tuple(A.shape), \" (layers, heads, query, key)\")","lines":[{"from":1,"to":2,"say":"**토크나이저(Tokenizer)** 와 모델을 가져오고, 잔소리 로그를 꺼요."},{"from":4,"to":4,"say":"쓸 모델 이름이에요. 주석처럼 처음에는 250MB 를 내려받아요."},{"from":5,"to":5,"say":"그 모델에 맞는 **토크나이저(Tokenizer)** 를 불러와요."},{"from":6,"to":9,"say":"어텐션을 꺼낼 수 있는 방식으로 모델을 불러와요. 옛 버전이면 그냥 불러와요."},{"from":10,"to":10,"say":"채점 모드로 바꿔요. 학습하지 않아요."},{"from":12,"to":12,"say":"강의에 나온 그 문장이에요. 주어와 동사가 멀리 떨어져 있어요."},{"from":14,"to":15,"say":"문장을 받아 **토큰(Token)** 번호로 바꾸는 함수예요."},{"from":16,"to":17,"say":"**기울기(Gradient)** 없이 모델을 돌리되 어텐션도 같이 받아요."},{"from":18,"to":18,"say":"층마다 온 어텐션을 쌓고 0번 문장만 골라요. 주석처럼 (층, 헤드, 쿼리, 키) 예요."},{"from":19,"to":19,"say":"어텐션과 토큰 글자 목록을 함께 돌려줘요."},{"from":21,"to":21,"say":"그 문장으로 함수를 불러요."},{"from":22,"to":23,"say":"토큰 목록과 어텐션의 **모양(Shape)** 을 출력해요."}],"link":"강의 N4 p.48 What heads actually learn (studied in BERT)"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`tokens    : ['[CLS]', 'the', 'chef', 'who', 'ran', 'to', 'the', 'store', 'was', 'tired', '.', '[SEP]']`","`attention : (6, 12, 12, 12)  (layers, heads, query, key)`"]},{"kind":"points","head":"출력 읽기","items":["토큰은 `[CLS] the chef who ran to the store was tired . [SEP]` 열두 개예요.","`[CLS]` 와 `[SEP]` 는 **토크나이저(Tokenizer)** 가 붙이는 특수 **토큰(Token)** 이에요. 뜻이 없어요.","어텐션 **모양(Shape)** 은 (6, 12, 12, 12) 예요. 6층, 12**헤드(Head)**, 쿼리 12, 키 12."]}],"pass4":[{"kind":"check","q":"어텐션 **모양(Shape)** (6, 12, 12, 12) 에서 앞의 6 과 12 는 각각 무엇인가요?","choices":["층 6개와 **헤드(Head)** 12개","**토큰(Token)** 6개와 12개","쿼리와 키","묶음과 차원"],"a":0,"why":"뒤의 12, 12 는 토큰 12개가 서로를 보는 어텐션 행렬이에요. 그래서 헤드가 모두 72개예요."},{"kind":"warn","head":"헷갈리는 점","items":["내려받기 진행 막대와 경고문은 출력에 섞여 나와요. 오류가 아니에요.","DistilBERT 는 **버트(BERT)** 계열이라 미래를 가리지 않아요. 양쪽을 다 봐요."]}]},{"p":26,"title":"5.1 한 층의 헤드 열두 개를 한눈에","terms":["Head","Multi-Head Attention (MHA)","Attention Weight","BERT"],"pass1":[{"kind":"say","lines":["같은 문장에 대해 한 층의 **헤드(Head)** 열두 개를 나란히 그려요.","서로 전혀 다른 일을 하고 있는 게 한눈에 보여요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**All 12 heads of one layer** = 한 층의 헤드 열두 개 전부.","**Every panel is one head's attention matrix** = 칸 하나가 **헤드(Head)** 하나의 어텐션 행렬이에요.","**They are clearly not doing the same thing** = 서로 같은 일을 하고 있지 않아요."]},{"kind":"pyterm","name":"subplots(2, 6) 와 axes.flat","say":["`plt.subplots(2, 6, ...)` 는 2행 6열, 곧 12칸짜리 그림판을 만들어요.","`axes.flat` 은 그 12칸을 한 줄로 펴서 차례로 꺼내요.","`enumerate(...)` 는 번호와 값을 함께 줘요."],"example":"print(list(enumerate('ab')))","out":"[(0, 'a'), (1, 'b')]"},{"kind":"pyterm","name":"vmin, vmax 로 색 기준 맞추기","say":["`imshow(..., vmin=0, vmax=1)` 은 색의 기준을 0 과 1 로 못 박아요.","칸마다 기준이 다르면 진하기를 비교할 수 없어서 이렇게 맞춰 둬요."],"example":"print((0, 1))","out":"(0, 1)"}],"pass3":[{"kind":"code","head":"한 층의 헤드 열두 개 그리기","file":"Lab3 노트북 셀 42","code":"LAYER = 1\nfig, axes = plt.subplots(2, 6, figsize=(15, 5.2))\nfor h, axx in enumerate(axes.flat):\n    axx.imshow(A[LAYER, h], cmap=\"Blues\", vmin=0, vmax=1)\n    axx.set_title(f\"L{LAYER} H{h}\", fontsize=10)\n    axx.set_xticks([]); axx.set_yticks([])\nfig.suptitle(f\"DistilBERT layer {LAYER}: all 12 heads, same sentence\", y=1.02)\nplt.tight_layout(); plt.show()","lines":[{"from":1,"to":1,"say":"1번 층을 보기로 정해요. 번호는 0부터예요."},{"from":2,"to":2,"say":"2행 6열, 곧 12칸짜리 그림판을 만들어요."},{"from":3,"to":3,"say":"12칸을 차례로 꺼내며 **헤드(Head)** 번호도 함께 받아요."},{"from":4,"to":4,"say":"그 헤드의 **어텐션 가중치(Attention Weight)** 를 파란 히트맵으로 칠해요."},{"from":5,"to":5,"say":"칸마다 L1 H0 같은 작은 제목을 붙여요."},{"from":6,"to":6,"say":"눈금을 지워요. 12칸이라 눈금이 있으면 지저분해요."},{"from":7,"to":7,"say":"그림 전체 제목을 붙여요."},{"from":8,"to":8,"say":"여백을 정리하고 화면에 띄워요."}],"link":"강의 N4 p.48 서로 다른 일을 배우는 헤드들"},{"kind":"points","head":"저장된 출력","items":["`<Figure size 1500x520 with 12 Axes>` 와 그림이 나와요. 숫자 출력은 없어요.","어떤 칸은 대각선, 어떤 칸은 왼쪽 세로줄, 어떤 칸은 얼룩덜룩해요.","같은 **버트(BERT)** 의 같은 층인데 **헤드(Head)** 마다 무늬가 달라요."]}],"pass4":[{"kind":"check","q":"칸마다 무늬가 다른 것이 보여 주는 것은?","choices":["**멀티 헤드 어텐션(Multi-Head Attention)** 의 헤드들이 서로 다른 관점을 배웠다는 것","학습이 덜 됐다는 것","그림이 잘못됐다는 것","문장이 짧다는 것"],"a":0,"why":"교수님 말처럼 헤드 1은 문법, 헤드 2는 가까운 문맥 같은 식으로 일을 나눠 맡아요."},{"kind":"warn","head":"헷갈리는 점","items":["색 기준을 0 과 1 로 고정했기 때문에 칸끼리 진하기를 비교할 수 있어요.","층 번호를 바꾸면 무늬도 달라져요. 낮은 층과 높은 층이 보는 것이 달라요."]}]},{"p":27,"title":"5.2 이름을 붙일 수 있는 헤드 세 개","terms":["Head","Alignment","Interpretability","Attention Weight"],"pass1":[{"kind":"say","lines":["72개 **헤드(Head)** 를 전부 훑어서 하는 일이 또렷한 셋을 골랐어요.","다음 토큰 헤드, 이전 토큰 헤드, 그리고 주어와 동사를 잇는 헤드예요."]},{"kind":"points","head":"세 헤드의 이름","items":["L1 H9: 다음 **토큰(Token)** 헤드. 행의 거의 전부가 바로 뒷자리에 몰려요.","L0 H2: 이전 토큰 헤드. 그 거울상이에요.","L2 H10: 주어와 동사를 잇는 헤드. was 가 chef 를 돌아봐요."]}],"pass2":[{"kind":"compare","head":"세 헤드 정리","cols":["이름","보는 곳","뜻"],"rows":[["L1 H9","자리 i + 1","바로 다음 **토큰(Token)**"],["L0 H2","자리 i - 1","바로 이전 토큰"],["L2 H10","관계절을 건너뛴 주어","문법적 **정렬(Alignment)**"]]},{"kind":"points","head":"영어 문장의 뜻","items":["**the next-token head** = 다음 토큰 **헤드(Head)**.","**The mirror image** = 그 거울상이에요.","**skipping the whole relative clause** = 관계절 전체를 건너뛰어요.","**nobody supervised it** = 아무도 가르쳐 주지 않았어요."]},{"kind":"points","head":"문장 구조 보기","items":["The chef who ran to the store was tired.","주어는 chef 인데 동사 was 까지 'who ran to the store' 가 끼어 있어요.","그래도 was 가 chef 를 정확히 돌아봐요. 이것이 **정렬(Alignment)** 이에요."]}],"pass3":[{"kind":"points","head":"강의와 짝","items":["N4 p.26 이 '**정렬(Alignment)** 은 공짜로 학습된다' 는 쪽이에요.","N4 p.48 이 '**버트(BERT)** 에서 헤드가 실제로 무엇을 배우는지 연구됐다' 는 쪽이에요.","어떤 헤드는 이전, 다음 토큰을 좇고, 어떤 헤드는 문법 관계를 좇아요."]}],"pass4":[{"kind":"check","q":"L2 H10 이 흥미로운 까닭은?","choices":["관계절을 건너뛰고 주어를 찾는 문법 **정렬(Alignment)** 을 아무도 안 가르쳤는데 배웠기 때문","가장 진하기 때문","1번 층이기 때문","**어텐션 가중치(Attention Weight)** 가 1 이기 때문"],"a":0,"why":"통계 기반 번역에서는 정렬 모델을 따로 만들어야 했어요. 어텐션은 덤으로 배워요."},{"kind":"warn","head":"헷갈리는 점","items":["헤드 번호는 이 모델, 이 문장에서 찾은 것이에요. 다른 모델에서는 번호가 달라요.","**해석 가능성(Interpretability)** 은 '보인다' 까지예요. 다음 쪽에서 그 한계를 봐요."]}]},{"p":28,"title":"세 헤드를 확대해서 숫자까지 보기","terms":["Head","Alignment","Attention Weight","Token","Query","Key"],"pass1":[{"kind":"say","lines":["세 **헤드(Head)** 를 크게 그리고, was 가 어디를 봤는지 상위 3개를 숫자로 찍어요."]}],"pass2":[{"kind":"pyterm","name":"리스트 안의 튜플과 zip","say":["`picks = [(1, 9, \"next-token head\"), ...]` 는 (층, **헤드(Head)**, 이름) 묶음 목록이에요.","`zip(axes, picks)` 는 그림 칸과 묶음을 짝지어 하나씩 꺼내요.","`for axx, (l, h, name) in zip(...)` 처럼 묶음을 바로 풀어 받을 수 있어요."],"example":"print(list(zip('ab', (1, 2))))","out":"[('a', 1), ('b', 2)]"},{"kind":"pyterm","name":"리스트의 .index()","say":["`tokens.index(\"was\")` 는 목록에서 was 가 몇 번째인지 알려 줘요.","그 번호로 어텐션 행렬의 그 줄을 꺼내요."],"example":"print(['a', 'b', 'c'].index('b'))","out":"1"},{"kind":"pyterm","name":"argsort(descending=True)","say":["값이 큰 순서대로 '번호' 를 줄 세워요. 값이 아니라 자리 번호예요.","`[:3]` 을 붙이면 가장 큰 세 자리만 남아요."],"example":"import torch\nprint(torch.tensor([0.1, 0.9, 0.5]).argsort(descending=True))","out":"tensor([1, 2, 0])"}],"pass3":[{"kind":"code","head":"세 헤드 확대하고 was 의 상위 3개 보기","file":"Lab3 노트북 셀 44","code":"picks = [(1, 9, \"next-token head\"), (0, 2, \"previous-token head\"),\n         (2, 10, \"subject-verb head\")]\n\nfig, axes = plt.subplots(1, 3, figsize=(15, 4.6))\nfor axx, (l, h, name) in zip(axes, picks):\n    axx.imshow(A[l, h], cmap=\"Blues\", vmin=0, vmax=1)\n    axx.set_xticks(range(len(tokens))); axx.set_xticklabels(tokens, rotation=90, fontsize=8)\n    axx.set_yticks(range(len(tokens))); axx.set_yticklabels(tokens, fontsize=8)\n    axx.set_title(f\"L{l} H{h} - {name}\")\nplt.tight_layout(); plt.show()\n\ni_was, i_chef = tokens.index(\"was\"), tokens.index(\"chef\")\nrow = A[2, 10, i_was]\norder = row.argsort(descending=True)[:3]\nprint(\"L2 H10, the row for 'was' - top 3 keys:\")\nfor j in order:\n    print(f\"   {tokens[j]:<8} {row[j]:.3f}\")","lines":[{"from":1,"to":2,"say":"볼 **헤드(Head)** 세 개를 (층, 헤드, 이름) 으로 적어 둬요."},{"from":4,"to":4,"say":"1행 3열 그림판을 만들어요."},{"from":5,"to":5,"say":"그림 칸과 헤드 정보를 짝지어 하나씩 꺼내요."},{"from":6,"to":6,"say":"그 헤드의 **어텐션 가중치(Attention Weight)** 를 히트맵으로 칠해요."},{"from":7,"to":8,"say":"가로축과 세로축 눈금에 **토큰(Token)** 글자를 붙여요. 가로가 **키(Key)**, 세로가 **쿼리(Query)** 예요."},{"from":9,"to":9,"say":"칸마다 층, 헤드 번호와 이름을 제목으로 붙여요."},{"from":10,"to":10,"say":"여백을 정리하고 화면에 띄워요."},{"from":12,"to":12,"say":"was 와 chef 가 몇 번째 토큰인지 찾아요."},{"from":13,"to":13,"say":"L2 H10 에서 was 줄을 꺼내요. 곧 was 가 어디를 보는지예요."},{"from":14,"to":14,"say":"값이 큰 순서로 자리 번호를 줄 세우고 앞의 세 개만 남겨요."},{"from":15,"to":15,"say":"머리글을 출력해요."},{"from":16,"to":17,"say":"상위 3개 **토큰(Token)** 과 그 가중치를 한 줄씩 출력해요."}],"link":"강의 N4 p.26 Alignment, p.48 헤드가 배우는 것"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`<Figure size 1500x460 with 3 Axes>`","`[그림 출력]`","`L2 H10, the row for 'was' - top 3 keys:`","`chef     0.308`","`to       0.228`","`who      0.126`"]},{"kind":"points","head":"숫자 읽기","items":["chef 0.308 이 1등이에요. was 의 주의 31% 가 주어로 가요.","to 0.228, who 0.126 이 그다음이에요. 나머지는 여러 곳에 흩어져요.","1등이 주어라는 것이 이 **헤드(Head)** 를 '주어와 동사 헤드' 라고 부르는 근거예요."]}],"pass4":[{"kind":"check","q":"was 줄의 1등이 chef (0.308) 라는 뜻은?","choices":["was 가 관계절을 건너뛰고 주어 chef 를 가장 많이 봤다는 뜻","chef 가 정답이라는 뜻","확률이 30% 라는 뜻","chef 가 동사라는 뜻"],"a":0,"why":"행 하나가 한 **쿼리(Query)** 의 **어텐션 가중치(Attention Weight)** 이고, 다 더하면 1 이에요."},{"kind":"warn","head":"헷갈리는 점","items":["0.308 은 절반도 안 돼요. 1등이라는 것이지 압도적이라는 뜻이 아니에요.","**정렬(Alignment)** 이 보인다고 해서 모델이 문법을 '이해한다' 고 말하면 지나쳐요."]}]},{"p":29,"title":"한 문장의 우연인가: 세 문장으로 더 확인","terms":["Head","Alignment","Interpretability","Attention Weight","Token"],"pass1":[{"kind":"say","lines":["주어와 동사 **헤드(Head)** 가 정말 일반적인지, 같은 구조의 문장 셋으로 더 시험해요.","운이 좋았던 건지 아닌지 확인하는 태도가 중요해요."]}],"pass2":[{"kind":"points","head":"시험할 세 문장","items":["The students that the teacher praised were happy. (were → students)","The dog that chased the cat is sleeping. (is → dog)","The keys to the cabinet are on the table. (are → keys)","셋 다 주어와 동사 사이에 다른 말이 끼어 있어요."]},{"kind":"pyterm","name":"튜플 목록을 for 에서 풀기","say":["`for sent, verb, subj in tests:` 는 묶음 셋을 한 번에 세 변수로 받아요.","목록의 각 칸이 (문장, 동사, 주어) 세 쪽짜리 묶음이에요."],"example":"for a, b in [(1, 2), (3, 4)]:\n    print(a + b)","out":"3\n7"},{"kind":"pyterm","name":".tolist().index() 로 순위 구하기","say":["`row.argsort(descending=True)` 로 큰 순서 번호를 얻어요.","`.tolist().index(정답 자리)` 는 그 안에서 정답이 몇 번째인지 찾아요.","거기에 1 을 더하면 1등, 2등 같은 순위가 돼요."],"example":"print([1, 2, 0].index(0) + 1)","out":"3"}],"pass3":[{"kind":"code","head":"같은 구조의 세 문장으로 다시 재기","file":"Lab3 노트북 셀 46","code":"tests = [(\"The students that the teacher praised were happy.\", \"were\", \"students\"),\n         (\"The dog that chased the cat is sleeping.\",          \"is\",   \"dog\"),\n         (\"The keys to the cabinet are on the table.\",         \"are\",  \"keys\")]\n\nprint(\"L2 H10 - where does the verb look?\")\nfor sent, verb, subj in tests:\n    Ai, ti = attention_for(sent)\n    row = Ai[2, 10, ti.index(verb)]\n    rank = row.argsort(descending=True).tolist().index(ti.index(subj)) + 1\n    top3 = [ti[j] for j in row.argsort(descending=True)[:3]]\n    print(f\"  '{verb}' -> subject '{subj}' has weight {row[ti.index(subj)]:.3f}, \"\n          f\"rank {rank}   (top 3: {top3})\")\n\nprint(\"\\n-> The subject is always in the top 3, usually first or second.\")\nprint(\"   Strong, but not a rule the model follows perfectly. Be honest about that.\")","lines":[{"from":1,"to":3,"say":"시험할 (문장, 동사, 주어) 셋을 적어 둬요."},{"from":5,"to":5,"say":"머리글을 출력해요."},{"from":6,"to":6,"say":"세 묶음을 하나씩 꺼내요."},{"from":7,"to":7,"say":"그 문장으로 어텐션과 **토큰(Token)** 목록을 다시 구해요."},{"from":8,"to":8,"say":"L2 H10 에서 그 동사의 줄을 꺼내요."},{"from":9,"to":9,"say":"그 줄에서 주어가 몇 등인지 구해요."},{"from":10,"to":10,"say":"**어텐션 가중치(Attention Weight)** 가 큰 상위 3개 토큰을 뽑아요."},{"from":11,"to":12,"say":"동사, 주어, 가중치, 순위, 상위 3개를 한 줄로 출력해요."},{"from":14,"to":15,"say":"주어는 늘 상위 3위 안이고 보통 1, 2등이지만, 완벽한 규칙은 아니라고 솔직히 적어요."}],"link":"강의 N4 p.26 Alignment, 그리고 해석에 대한 조심스러움"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`L2 H10 - where does the verb look?`","`'were' -> subject 'students' has weight 0.253, rank 2   (top 3: ['praised', 'students', 'that'])`","`'is' -> subject 'dog' has weight 0.206, rank 2   (top 3: ['chased', 'dog', 'cat'])`","`'are' -> subject 'keys' has weight 0.686, rank 1   (top 3: ['keys', 'to', 'the'])`","`-> The subject is always in the top 3, usually first or second.`","`Strong, but not a rule the model follows perfectly. Be honest about that.`"]},{"kind":"steps","head":"세 줄을 나란히 읽기","steps":["were → students: 가중치 0.253, 순위 2등","is → dog: 가중치 0.206, 순위 2등","are → keys: 가중치 0.686, 순위 1등","세 번 모두 상위 3위 안에 들어요."],"answer":"강하지만 완벽하지는 않아요. 노트북 말대로 그 점을 솔직히 말하는 게 좋은 태도예요."}],"pass4":[{"kind":"check","q":"세 문장 중 두 번은 주어가 2등이었어요. 올바른 결론은?","choices":["경향은 뚜렷하지만 모델이 완벽히 따르는 규칙은 아니에요","이 **헤드(Head)** 는 쓸모없어요","코드가 틀렸어요","주어는 늘 1등이에요"],"a":0,"why":"노트북 원문: Strong, but not a rule the model follows perfectly. Be honest about that."},{"kind":"warn","head":"헷갈리는 점","items":["세 문장은 표본이 아주 작아요. 이 정도로 '항상 그렇다' 고 말하면 안 돼요.","**해석 가능성(Interpretability)** 실험은 이렇게 반례까지 같이 보고해야 믿을 수 있어요."]}]},{"p":30,"title":"5.3 그리고 많은 헤드는 거의 아무 일도 안 해요","terms":["Head","Attention Weight","Multi-Head Attention (MHA)","Token","Tokenizer"],"pass1":[{"kind":"say","lines":["강의는 놀랄 만큼 많은 **헤드(Head)** 를 잘라내도 성능이 안 떨어진다고 했어요.","확인하는 방법 하나는, 뜻 없는 특수 **토큰(Token)** 에만 주의를 쏟는 헤드를 찾는 거예요."]},{"kind":"analogy","head":"의견 없음","scene":"회의에서 질문을 받을 때마다 천장만 쳐다보는 사람이 있어요. 자리는 차지하지만 의견은 없어요.","map":[["천장 쳐다보기","[CLS] 와 [SEP] 에 주의 몰기"],["의견 없는 참석자","거의 일하지 않는 **헤드(Head)**"],["자리를 빼도 괜찮음","잘라내도 성능이 안 떨어짐"]]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**many heads do almost nothing** = 많은 **헤드(Head)** 가 거의 아무 일도 안 해요.","**a surprising number of heads can be pruned with no loss** = 놀랄 만큼 많은 헤드를 잘라내도 손해가 없어요.","**which carry no content** = 그 토큰들은 내용이 없어요.","**That is attention's version of no opinion** = 어텐션 판 '의견 없음' 이에요."]},{"kind":"pyterm","name":"여러 축 한꺼번에 고르기","say":["`A[:, :, :, [i_cls, i_sep]]` 은 마지막 축에서 두 자리만 골라요.","`.sum(-1)` 로 둘을 더하고 `.mean(-1)` 로 모든 **쿼리(Query)** 에 대해 평균을 내요.","결과는 (층, **헤드(Head)**) 짜리 표예요."],"example":"import torch\nprint(tuple(torch.zeros(6, 12, 12, 12)[:, :, :, [0, 1]].sum(-1).mean(-1).shape))","out":"(6, 12)"},{"kind":"pyterm","name":".flatten() 과 divmod","say":["`mass.flatten()` 은 6 x 12 표를 72칸 한 줄로 펴요.","`divmod(번호, 12)` 는 몫과 나머지를 함께 줘요. 몇 층 몇 번 **헤드(Head)** 인지 되찾는 데 써요."],"example":"print(divmod(27, 12))","out":"(2, 3)"},{"kind":"pyterm","name":"(flat > 0.7).float().mean()","say":["참, 거짓을 1, 0 으로 바꿔 평균을 내면 '조건을 만족하는 비율' 이 나와요.","여기서는 특수 토큰에 70% 넘게 쏟는 헤드의 비율이에요."],"example":"import torch\nprint((torch.tensor([0.9, 0.1]) > 0.7).float().mean().item())","out":"0.5"}],"pass3":[{"kind":"code","head":"특수 토큰에 쏟는 주의를 층과 헤드별로 재기","file":"Lab3 노트북 셀 48","code":"i_cls, i_sep = tokens.index(\"[CLS]\"), tokens.index(\"[SEP]\")\nmass = A[:, :, :, [i_cls, i_sep]].sum(-1).mean(-1)          # (layers, heads)\n\nfig, ax = plt.subplots(figsize=(8, 2.8))\nim = ax.imshow(mass, cmap=\"Oranges\", vmin=0, vmax=1, aspect=\"auto\")\nax.set_xlabel(\"head\"); ax.set_ylabel(\"layer\")\nax.set_title(\"share of attention spent on [CLS] / [SEP]\")\nfig.colorbar(im, ax=ax)\nplt.tight_layout(); plt.show()\n\nflat = mass.flatten()\nprint(f\"average over all {flat.numel()} heads : {flat.mean():.2f}\")\nprint(f\"heads spending more than 70% there   : {(flat > 0.7).float().mean()*100:.0f}%\")\nl, h = divmod(int(flat.argmax()), mass.shape[1])\nprint(f\"the most extreme one                 : L{l} H{h} at {flat.max():.2f}\")","lines":[{"from":1,"to":1,"say":"[CLS] 와 [SEP] **토큰(Token)** 이 몇 번째인지 찾아요."},{"from":2,"to":2,"say":"각 헤드가 그 두 자리에 쏟은 **어텐션 가중치(Attention Weight)** 를 더하고 평균 내요."},{"from":4,"to":4,"say":"그림 칸을 하나 만들어요."},{"from":5,"to":5,"say":"(층, **헤드(Head)**) 표를 주황 히트맵으로 칠해요. 기준은 0 과 1 이에요."},{"from":6,"to":6,"say":"가로축은 헤드, 세로축은 층이에요."},{"from":7,"to":7,"say":"제목을 붙여요."},{"from":8,"to":8,"say":"색 막대를 붙여요."},{"from":9,"to":9,"say":"여백을 정리하고 화면에 띄워요."},{"from":11,"to":11,"say":"표를 72칸 한 줄로 펴요."},{"from":12,"to":12,"say":"72개 헤드 전체 평균을 출력해요."},{"from":13,"to":13,"say":"70% 넘게 쏟는 헤드의 비율을 출력해요."},{"from":14,"to":14,"say":"가장 심한 헤드가 몇 층 몇 번인지 되찾아요."},{"from":15,"to":15,"say":"그 헤드와 값을 출력해요."}],"link":"강의 N4 p.48 a surprising number learn almost nothing and can be pruned"},{"kind":"points","head":"강의 노트북에 저장된 출력","items":["`<Figure size 800x280 with 2 Axes>`","`[그림 출력]`","`average over all 72 heads : 0.49`","`heads spending more than 70% there   : 14%`","`the most extreme one                 : L2 H3 at 0.93`"]},{"kind":"steps","head":"세 숫자 읽기","steps":["72개 **헤드(Head)** 전체 평균이 0.49 예요. 절반쯤을 뜻 없는 자리에 써요.","70% 넘게 쏟는 헤드가 14% 예요. 72개 중 열 개쯤이에요.","가장 심한 것은 L2 H3 으로 0.93 이에요.","곧 그 헤드는 주의의 93% 를 [CLS] 와 [SEP] 에 버려요."],"answer":"**멀티 헤드 어텐션(Multi-Head Attention)** 의 헤드가 모두 열심히 일하는 것은 아니에요."},{"kind":"points","head":"저장된 출력에 대해","items":["그림(`<Figure size 800x280 with 2 Axes>`)과 숫자 세 줄이 함께 나와요.","그림에서 주황색이 진한 칸이 '의견 없음' 헤드예요."]}],"pass4":[{"kind":"check","q":"어떤 **헤드(Head)** 가 [CLS] 와 [SEP] 에 주의를 93% 쏟는다는 것은?","choices":["그 헤드는 사실상 아무 정보도 옮기지 않는다는 뜻","그 헤드가 가장 중요하다는 뜻","**토크나이저(Tokenizer)** 가 잘못됐다는 뜻","학습이 덜 됐다는 뜻"],"a":0,"why":"[CLS] 와 [SEP] 는 내용이 없는 특수 **토큰(Token)** 이에요. 거기만 본다는 건 의견이 없다는 뜻이에요."},{"kind":"warn","head":"헷갈리는 점","items":["'거의 일 안 하는 헤드가 있다' 가 '멀티 헤드가 쓸모없다' 는 뜻은 아니에요.","이 측정은 문장 하나로 잰 값이에요. 진짜 가지치기 연구는 훨씬 많은 문장으로 해요."]}]},{"p":31,"title":"5.4 가기 전에 한 가지 경고","terms":["Interpretability","Attention Weight","Head","Attention"],"pass1":[{"kind":"say","lines":["**어텐션 가중치(Attention Weight)** 는 정보를 어디서 가져왔는지를 보여 줘요.","모델이 왜 그렇게 답했는지를 보여 주지는 않아요.","그림은 즐기되 거기서 과한 주장을 끌어내지는 마세요."]}],"pass2":[{"kind":"points","head":"영어 문장의 뜻","items":["**where information was pulled from** = 정보를 어디서 가져왔는지.","**not why the model answered the way it did** = 모델이 왜 그렇게 답했는지가 아니에요.","**A head pointing at chef is suggestive, not proof** = **헤드(Head)** 가 chef 를 가리키는 것은 시사적일 뿐 증명이 아니에요.","**attention is not explanation** = 어텐션은 설명이 아니다.","**do not over-claim from them** = 그림에서 과한 주장을 하지 마세요."]},{"kind":"compare","head":"무엇을 말할 수 있고 없나","cols":["보여 주는 것","보여 주지 않는 것"],"rows":[["이 자리에서 저 자리로 정보가 갔다","그래서 이 답이 나왔다"],["**어텐션 가중치(Attention Weight)** 의 분포","모델의 판단 근거 전체"],["**헤드(Head)** 마다 무늬가 다르다","그 무늬가 곧 문법 지식이다"]]}],"pass3":[{"kind":"points","head":"왜 이 경고가 중요한가","items":["**해석 가능성(Interpretability)** 은 딥러닝에서 드물고 귀한 성질이에요(N4 p.25).","그만큼 과하게 읽기도 쉬워요. 양쪽을 다투는 연구가 실제로 있어요.","팀 프로젝트에서 어텐션 그림을 쓸 때 특히 조심해야 할 점이에요."]}],"pass4":[{"kind":"warn","head":"시험과 프로젝트에서 조심할 점","items":["'**어텐션(Attention)** 그림이 이러니 모델이 이렇게 판단했다' 는 지나친 주장이에요.","'이 자리에서 정보를 많이 가져왔다' 까지가 안전한 표현이에요."]},{"kind":"english","head":"답안 문장","en":"어텐션 가중치는 정보가 어느 위치에서 왔는지를 보여 주는 단서일 뿐, 모델이 그렇게 답한 이유에 대한 설명은 아니다.","ko":"해석 가능성은 장점이지만 증명이 아니에요. 그래서 attention is not explanation 논쟁이 있어요.","tip":"'어디서 왔나' 는 되고 '왜 그랬나' 는 안 된다고 외워요."},{"kind":"check","q":"어텐션 그림으로 말할 수 있는 것은?","choices":["정보가 어느 자리에서 왔는지","모델이 왜 그 답을 골랐는지","모델이 문법을 이해한다는 것","모델의 정확도"],"a":0,"why":"**해석 가능성(Interpretability)** 의 범위를 넘지 않는 것이 중요해요."}]},{"p":32,"title":"오늘 만든 것 정리와 다음 주","terms":["Attention","Self-Attention","Multi-Head Attention (MHA)","Transformer","Positional Encoding","Causal Masking","Position-wise Feed-Forward Network (FFN)","Residual Connection","Layer Normalization (LayerNorm)","BERT","Head"],"pass1":[{"kind":"say","lines":["오늘 **트랜스포머(Transformer)** 블록을 처음부터 끝까지 직접 만들었어요.","그리고 강의의 주장 하나하나를 숫자로 확인했어요."]},{"kind":"points","head":"오늘 만든 것 일곱 가지","items":["1. **어텐션(Attention)** = 점수 → 소프트맥스 → 가중합. NumPy 세 줄.","2. 루트 d_k 는 장식이 아니에요. 없으면 소프트맥스가 포화되고 기울기가 죽어요.","3. **셀프 어텐션(Self-Attention)** 은 한 시퀀스에서 Q, K, V 를 만들어요.","4. 장벽 세 개를 직접 측정했어요. 순서, 평균, 미래.","5. **멀티 헤드 어텐션(Multi-Head Attention)** 은 헤드 하나와 비용이 같아요.","6. Pre-LN **트랜스포머(Transformer)** 블록을 2초 만에 학습시키고 어텐션 지도를 읽었어요.","7. DistilBERT 의 진짜 **헤드(Head)** 들을 봤어요."]}],"pass2":[{"kind":"points","head":"장벽과 처방 다시 한 번","items":["순서 없음 → **순열 등변성(Permutation Equivariance)**, 오차 1e-15 → **위치 인코딩(Positional Encoding)**","평균만 냄 → 밸류 범위 안에 갇힘 → **위치별 피드포워드 신경망(FFN)**","미래를 봄 → 소프트맥스 전에 음의 무한대 → **인과 마스킹(Causal Masking)**","그리고 깊게 쌓기 위한 **잔차 연결(Residual Connection)** 과 **층 정규화(Layer Normalization)**"]},{"kind":"points","head":"더 해보고 싶다면(선택)","items":["Part 4 를 n_heads=2 로 다시 돌려 두 **헤드(Head)** 를 함께 그려 보기. 일을 나눠 맡을까요?","과제 길이를 K = 12 로 늘려 보기. 한 층으로도 될까요?","Part 5 에서 klue/bert-base 로 한국어 문장을 넣고 조사와 명사를 잇는 헤드 찾아보기.","**사인 코사인 위치 인코딩(Sinusoidal Positional Encoding)** 대신 학습되는 위치 벡터로 바꿔 보기도 좋아요."]}],"pass3":[{"kind":"prof","when":"4주차 3교시 수업","lines":["교수님: 실습 자료에 대해서도 질문이 있으면 메일 편하게 주세요.","질문이 크리티컬해서 다 알려드려야 된다 싶으면 공지 사항으로 올리겠습니다."]},{"kind":"points","head":"다음 주 예고","items":["5주차는 사전 학습 언어 모델이에요. **버트(BERT)**, GPT, T5.","오늘 만든 그 블록을 세상의 모든 텍스트로 학습시킨 뒤 미세조정하는 이야기예요.","Lab 4 에서는 한국어 **버트(BERT)** 를 NSMC 로 미세조정해요."]},{"kind":"points","head":"꼭 읽으라고 한 논문","items":["교수님: Attention Is All You Need 는 인공지능 학과로서 매우 중요한 논문이에요.","무조건 꼭 읽어 보시는 걸 매우 추천하고, 읽어서 이해하면 시험도 잘 볼 수 있어요."]}],"pass4":[{"kind":"check","q":"오늘 실습에서 숫자로 직접 확인하지 못한 장벽은?","choices":["장벽 2(평균만 냄). 뒤집기는 순수한 배달이라 **위치별 피드포워드 신경망(FFN)** 없이도 풀려요","장벽 1(순서)","장벽 3(미래)","전부 확인했어요"],"a":0,"why":"대신 2.2 에서 출력이 밸류 범위를 벗어나지 못한다는 것을 참/거짓으로 확인했어요."},{"kind":"english","head":"답안 문장","en":"트랜스포머 블록은 멀티 헤드 셀프 어텐션과 위치별 피드포워드 신경망을 잔차 연결과 층 정규화로 감싼 구조이며, 입력에 위치 인코딩을 더하고 언어 모델일 때는 인과 마스킹을 건다.","ko":"블록 하나를 한 문장으로 적을 수 있으면 강의 N4 p.58 의 '블록을 외워서 그려라' 를 할 수 있어요.","tip":"'위치 인코딩 + (정규화 → 어텐션 → 더하기) + (정규화 → FFN → 더하기)' 순서로 외워요."},{"kind":"warn","head":"마지막으로 헷갈리기 쉬운 점","items":["이 실습의 숫자는 씨앗을 고정해 얻은 값이에요. 학습 시간과 일부 소수점은 실행할 때마다 달라요.","Lab 3 은 수업에서 건너뛰었지만 강의 내용을 그대로 옮긴 것이라 시험 준비에 그대로 쓸 수 있어요."]}]}]};
